const DollarIcon = () => (
    <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5 md:h-6 md:w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
        <path strokeLinecap="round" strokeLinejoin="round" d="M12 8c-1.657 0-3 .895-3 2s1.343 2 3 2 3 .895 3 2-1.343 2-3 2m0-8c1.11 0 2.08.402 2.599 1M12 8V7m0 1v.01M12 16v-1m0 1v.01M12 16c-1.11 0-2.08-.402-2.599-1M12 16H9.401M12 8h2.599M12 8V6m0 12v-2m0-10V4m0 16v-2" />
    </svg>
);

export const RateDisplay: React.FC<RateDisplayProps> = ({ value, loading, label, description, currency, cities, cityLabels }) => {
  const [iconHighlightClass, setIconHighlightClass] = useState('');
  const [rateChangeClass, setRateChangeClass] = useState('');
  const prevValueRef = useRef(value);

  useEffect(() => {
    if (prevValueRef.current === value || value === 0) {
        prevValueRef.current = value;
        return;
    }

    setIconHighlightClass('bg-green-100 dark:bg-green-900/50 text-green-600 dark:text-green-400');
    const iconTimer = setTimeout(() => setIconHighlightClass(''), 500);

    if (value > prevValueRef.current) setRateChangeClass('text-green-500 dark:text-green-400');
    else if (value < prevValueRef.current) setRateChangeClass('text-red-500 dark:text-red-400');

    const rateTimer = setTimeout(() => setRateChangeClass(''), 500);

    prevValueRef.current = value;
    return () => {
      clearTimeout(iconTimer);
      clearTimeout(rateTimer);
    };
  }, [value]);

  const bgColor = 'bg-gray-50 dark:bg-gray-900/40';
  const textColor = 'text-gray-600 dark:text-gray-300';
  const iconClasses = iconHighlightClass || 'bg-gray-100 dark:bg-gray-700 text-green-600 dark:text-green-400';

  return (
    <div className={`p-4 md:p-5 rounded-xl ${bgColor} transition-colors duration-300 relative overflow-hidden`}>
      <div className="flex items-center justify-between mb-4">
        <div className="flex items-center space-x-2 md:space-x-3 rtl:space-x-reverse">
           <div className={`p-2 rounded-full border border-white/50 transition-colors duration-500 ${iconClasses}`}>
              <DollarIcon />
           </div>
          <div>
            <p className={`font-semibold ${textColor}`}>{label}</p>
            <p className="text-xs text-gray-500 dark:text-gray-400">{description}</p>
          </div>
        </div>
        <div className="text-right">
          <p className={`text-2xl md:text-3xl font-bold relative origin-right rtl:origin-left transition-colors duration-300 ${rateChangeClass || 'text-gray-900 dark:text-white'}`} dir="ltr">
            {Math.floor(value).toLocaleString()}
            {loading && (
              <span className="absolute -top-1 -right-4 h-3 w-3">
                <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-sky-400 opacity-75"></span>
                <span className="relative inline-flex rounded-full h-3 w-3 bg-sky-500"></span>
              </span>
            )}
          </p>
          <p className="text-sm font-medium text-gray-500 dark:text-gray-400">{currency}</p>
        </div>
      </div>

      {cities && cityLabels && (
        <div className="mt-4 pt-4 border-t border-gray-200 dark:border-gray-700/50">
          <p className="text-[10px] uppercase font-bold text-gray-400 dark:text-gray-500 tracking-widest mb-2 px-1">
            {cityLabels.regional}
          </p>
          <div className="grid grid-cols-3 gap-2">
            {[
              { id: 'suly', label: cityLabels.suly, val: cities.sulaymaniyah },
              { id: 'erbil', label: cityLabels.erbil, val: cities.erbil },
              { id: 'duhok', label: cityLabels.duhok, val: cities.duhok }
            ].map(city => {
                const diff = city.val - cities.sulaymaniyah;
                return (
                    <div key={city.id} className="bg-white/50 dark:bg-gray-800/40 p-2 rounded-lg border border-transparent hover:border-sky-500/30 transition-all">
                        <p className="text-[11px] font-bold text-gray-500 dark:text-gray-400 mb-0.5 truncate">{city.label}</p>
                        <p className="text-xs font-mono font-bold text-gray-800 dark:text-gray-200" dir="ltr">
                            {city.val.toLocaleString()}
                        </p>
                        {diff !== 0 && (
                            <p className={`text-[9px] font-bold mt-0.5 ${diff > 0 ? 'text-green-500' : 'text-red-500'}`} dir="ltr">
                                {diff > 0 ? '+' : ''}{diff.toLocaleString()}
                            </p>
                        )}
                        {diff === 0 && (
                            <div className="mt-1 h-0.5 w-4 bg-gray-300 dark:bg-gray-600 rounded-full"></div>
                        )}
                    </div>
                );
            })}
          </div>
        </div>
      )}
    </div>
  );
};

