import { useState, useEffect, useCallback, useRef } from 'react';
import type { ExchangeRateData, GroundingChunk, ExchangeRateErrorType, RateHistoryEntry } from '../types';
import { GoogleGenAI } from "@google/genai";

const FETCH_INTERVAL_MS = 2 * 60 * 60 * 1000; // 2 hours
const REFRESH_COOLDOWN_MS = 5 * 60 * 1000; // 5 minutes
const MAX_RETRIES = 3;
const RETRY_DELAY_MS = 2000;

const CACHED_RATE_KEY = 'dinarLive_cachedRate';
const CACHED_SOURCES_KEY = 'dinarLive_cachedSources';
const CACHED_HISTORY_KEY = 'dinarLive_cachedHistory';
const LAST_REFRESH_KEY = 'dinarLive_lastRefresh';

const getInitialState = <T,>(key: string): T | null => {
    try {
        const item = localStorage.getItem(key);
        return item ? JSON.parse(item) : null;
    } catch (error) {
        console.warn(`Error reading localStorage key “${key}”:`, error);
        return null;
    }
};

export const useExchangeRate = () => {
  const [rate, setRate] = useState<ExchangeRateData | null>(() => getInitialState<ExchangeRateData>(CACHED_RATE_KEY));
  const [sources, setSources] = useState<GroundingChunk[]>(() => getInitialState<GroundingChunk[]>(CACHED_SOURCES_KEY) || []);
  const [rateHistory, setRateHistory] = useState<RateHistoryEntry[]>(() => getInitialState<RateHistoryEntry[]>(CACHED_HISTORY_KEY) || []);
  const [isLoading, setIsLoading] = useState<boolean>(!rate);
  const [error, setError] = useState<ExchangeRateErrorType>(null);
  const [cooldownSeconds, setCooldownSeconds] = useState(0);

  const retryCount = useRef(0);
  const hasInitialData = useRef(!!rate);
  const cooldownTimerRef = useRef<number | null>(null);

  const updateCooldown = useCallback(() => {
    const lastRefreshTime = getInitialState<number>(LAST_REFRESH_KEY);
    if (!lastRefreshTime) {
      setCooldownSeconds(0);
      return;
    }
    const timeSinceLastRefresh = Date.now() - lastRefreshTime;
    const remainingCooldown = REFRESH_COOLDOWN_MS - timeSinceLastRefresh;

    if (remainingCooldown > 0) {
      setCooldownSeconds(Math.ceil(remainingCooldown / 1000));
    } else {
      setCooldownSeconds(0);
    }
  }, []);

  useEffect(() => {
    updateCooldown();
    cooldownTimerRef.current = window.setInterval(updateCooldown, 1000);
    return () => {
      if (cooldownTimerRef.current) clearInterval(cooldownTimerRef.current);
    };
  }, [updateCooldown]);

  const fetchExchangeRate = useCallback(async () => {
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

      const prompt = `
        **URGENT TASK:** Extract current $100 USD to IQD exchange rates for specific Iraqi cities.

        **PRIMARY SOURCE:** https://t.me/s/iraqborsa

        **EXTRACTION INSTRUCTIONS:**
        The Telegram messages follow this pattern: "*100$=145,950 سلێمانی پێنجی*"
        Find the most recent rates for:
        1. **Sulaymaniyah (سلێمانی)**: Extract the number next to "سلێمانی پێنجی".
        2. **Erbil (هەولێر)**: Extract the number next to "هەولێر پێنجی".
        3. **Duhok (دهۆک)**: Extract the number next to "دهۆک پێنجی".

        **Note:** These rates are for $100. They MUST be distinct if the source shows different values. 
        If a city is missing, use Sulaymaniyah's rate as the fallback.

        **SECONDARY DATA:**
        - Get EUR/USD, TRY/USD, GBP/USD, and IRT/USD (Toman) rates.
        - Get a 7-day price history for Sulaymaniyah.

        **OUTPUT JSON:**
        {
          "current": {
            "suly100Usd": number, 
            "erbil100Usd": number,
            "duhok100Usd": number,
            "eurPerUsd": number,
            "tryPerUsd": number,
            "gbpPerUsd": number,
            "irtPerUsd": number
          },
          "history": [
            { "date": "YYYY-MM-DD", "rate": number }
          ]
        }
      `;

      const response = await ai.models.generateContent({
        model: 'gemini-3-pro-preview',
        contents: prompt,
        config: {
          tools: [{ googleSearch: {} }],
        },
      });

      const rawText = response.text;
      const jsonMatch = rawText.match(/\{[\s\S]*\}/);

      if (!jsonMatch) throw new Error("Invalid API response format");

      const parsedData = JSON.parse(jsonMatch[0]);

      const suly = parsedData.current?.suly100Usd || 0;
      const erbil = parsedData.current?.erbil100Usd || 0;
      const duhok = parsedData.current?.duhok100Usd || 0;

      if (suly < 100000) throw new Error("Sulaymaniyah rate is missing or invalid");

      const newRate: ExchangeRateData = {
        iqd: suly / 100, // Sulaymaniyah is the benchmark
        cities: {
            sulaymaniyah: suly,
            erbil: erbil || suly,
            duhok: duhok || suly,
        },
        eurPerUsd: parsedData.current.eurPerUsd || 0,
        tryPerUsd: parsedData.current.tryPerUsd || 0,
        gbpPerUsd: parsedData.current.gbpPerUsd || 0,
        irtPerUsd: parsedData.current.irtPerUsd || 0,
        updated: new Date().toISOString(),
      };

      let newHistory: RateHistoryEntry[] = [];
      if (Array.isArray(parsedData.history)) {
          newHistory = parsedData.history
            .map((item: any) => ({
                date: item.date,
                rate: item.rate < 5000 ? item.rate * 100 : item.rate
            }))
            .filter((item: any) => item.rate > 100000)
            .sort((a: any, b: any) => new Date(a.date).getTime() - new Date(b.date).getTime())
            .slice(-7);
      }

      const uniqueChunks = Array.from(new Map((response.candidates?.[0]?.groundingMetadata?.groundingChunks as GroundingChunk[] ?? []).filter(item => item.web?.uri).map(item => [item.web!.uri, item])).values());

      setRate(newRate);
      setSources(uniqueChunks);
      if (newHistory.length > 0) {
          setRateHistory(newHistory);
          localStorage.setItem(CACHED_HISTORY_KEY, JSON.stringify(newHistory));
      }

      localStorage.setItem(CACHED_RATE_KEY, JSON.stringify(newRate));
      localStorage.setItem(CACHED_SOURCES_KEY, JSON.stringify(uniqueChunks));

      retryCount.current = 0;
      setError(null);
      setIsLoading(false);

    } catch (e: unknown) {
      console.error(`Fetch error:`, (e as Error).message);
      retryCount.current++;
      if (retryCount.current < MAX_RETRIES) {
        setTimeout(fetchExchangeRate, RETRY_DELAY_MS);
      } else {
        setError('FAILED_AFTER_RETRIES');
        setIsLoading(false);
      }
    }
  }, []);

  const startFetchCycle = useCallback(async (isManualRefresh = false) => {
    if (isManualRefresh) {
      const lastRefreshTime = getInitialState<number>(LAST_REFRESH_KEY);
      if (lastRefreshTime && (Date.now() - lastRefreshTime < REFRESH_COOLDOWN_MS)) {
        updateCooldown(); 
        return;
      }
      localStorage.setItem(LAST_REFRESH_KEY, JSON.stringify(Date.now()));
      updateCooldown();
    }

    retryCount.current = 0;
    setIsLoading(true);
    setError(null);
    await fetchExchangeRate();
  }, [fetchExchangeRate, updateCooldown]);

  useEffect(() => {
    if (!rate) startFetchCycle(false);
    const intervalId = setInterval(() => startFetchCycle(false), FETCH_INTERVAL_MS);
    return () => clearInterval(intervalId);
  }, [startFetchCycle, rate]);

  return {
    rate,
    sources,
    loading: isLoading,
    error,
    refetch: () => startFetchCycle(true),
    rateHistory,
    cooldownSeconds,
  };
};

