import { GoogleGenAI } from "@google/genai";

const FETCH_INTERVAL_MS = 2 * 60 * 60 * 1000; // 2 hours
const REFRESH_COOLDOWN_MS = 5 * 60 * 1000; // 5 minutes
const MAX_RETRIES = 3;
const RETRY_DELAY_MS = 2000;

const CACHED_RATE_KEY = 'dinarLive_cachedRate';
const CACHED_SOURCES_KEY = 'dinarLive_cachedSources';
const CACHED_HISTORY_KEY = 'dinarLive_cachedHistory';
const LAST_REFRESH_KEY = 'dinarLive_lastRefresh';

const getInitialState = <T,>(key: string): T | null => {
    try {
        const item = localStorage.getItem(key);
        return item ? JSON.parse(item) : null;
    } catch (error) {
        console.warn(`Error reading localStorage key “${key}”:`, error);
        return null;
    }
};

export const useExchangeRate = () => {
  const [rate, setRate] = useState<ExchangeRateData | null>(() => getInitialState<ExchangeRateData>(CACHED_RATE_KEY));
  const [sources, setSources] = useState<GroundingChunk[]>(() => getInitialState<GroundingChunk[]>(CACHED_SOURCES_KEY) || []);
  const [rateHistory, setRateHistory] = useState<RateHistoryEntry[]>(() => getInitialState<RateHistoryEntry[]>(CACHED_HISTORY_KEY) || []);
  const [isLoading, setIsLoading] = useState<boolean>(!rate);
  const [error, setError] = useState<ExchangeRateErrorType>(null);
  const [cooldownSeconds, setCooldownSeconds] = useState(0);

  const retryCount = useRef(0);
  const cooldownTimerRef = useRef<number | null>(null);

  const updateCooldown = useCallback(() => {
    const lastRefreshTime = getInitialState<number>(LAST_REFRESH_KEY);
    if (!lastRefreshTime) {
      setCooldownSeconds(0);
      return;
    }
    const timeSinceLastRefresh = Date.now() - lastRefreshTime;
    const remainingCooldown = REFRESH_COOLDOWN_MS - timeSinceLastRefresh;

    if (remainingCooldown > 0) {
      setCooldownSeconds(Math.ceil(remainingCooldown / 1000));
    } else {
      setCooldownSeconds(0);
    }
  }, []);

  useEffect(() => {
    updateCooldown();
    cooldownTimerRef.current = window.setInterval(updateCooldown, 1000);
    return () => {
      if (cooldownTimerRef.current) clearInterval(cooldownTimerRef.current);
    };
  }, [updateCooldown]);

  const fetchExchangeRate = useCallback(async () => {
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

      const prompt = `
        **TASK:** Fetch real-time exchange rates for IQD from two specific sources.

        **SOURCE 1 (Market Rates):** https://t.me/s/iraqborsa
        - Find messages like "*100$=145,950 سلێمانی پێنجی*"
        - Extract selling rates ($100) for: Sulaymaniyah (سلێمانی), Erbil (هەولێر), and Duhok (دهۆک).

        **SOURCE 2 (Official Rate):** https://www.creditbankofiraq.com.iq/personal/currency-rates.html
        - Find the "Sell Rate" for "US Dollar". Expect a value near 1320 or 132,000.

        **SECONDARY DATA:**
        - Fetch EUR/USD, TRY/USD, GBP/USD, and IRT/USD (Toman) rates.
        - Fetch 7-day rate history for Sulaymaniyah ($100 to IQD).

        **REQUIREMENT:** Return ONLY the following JSON. No text outside JSON.
        {
          "current": {
            "suly100Usd": number, 
            "erbil100Usd": number,
            "duhok100Usd": number,
            "officialRate": number,
            "eurPerUsd": number,
            "tryPerUsd": number,
            "gbpPerUsd": number,
            "irtPerUsd": number
          },
          "history": [
            { "date": "YYYY-MM-DD", "rate": number }
          ]
        }
      `;

      const response = await ai.models.generateContent({
        model: 'gemini-3-pro-preview',
        contents: prompt,
        config: {
          tools: [{ googleSearch: {} }],
        },
      });

      const rawText = response.text;
      const jsonMatch = rawText.match(/\{[\s\S]*\}/);

      if (!jsonMatch) throw new Error("Invalid response format");

      const parsedData = JSON.parse(jsonMatch[0]);

      const suly = parsedData.current?.suly100Usd || 0;
      const erbil = parsedData.current?.erbil100Usd || 0;
      const duhok = parsedData.current?.duhok100Usd || 0;
      const official = parsedData.current?.officialRate || 1320; // Default fallback if fetch fails but site is up

      if (suly < 100000) throw new Error("Sulaymaniyah market rate extraction failed");

      const normalizedOfficial = official > 10000 ? official / 100 : official;

      const newRate: ExchangeRateData = {
        iqd: suly / 100,
        centralBankRate: normalizedOfficial,
        cities: {
            sulaymaniyah: suly,
            erbil: erbil || suly,
            duhok: duhok || suly,
        },
        eurPerUsd: parsedData.current.eurPerUsd || 0,
        tryPerUsd: parsedData.current.tryPerUsd || 0,
        gbpPerUsd: parsedData.current.gbpPerUsd || 0,
        irtPerUsd: parsedData.current.irtPerUsd || 0,
        updated: new Date().toISOString(),
      };

      let newHistory: RateHistoryEntry[] = [];
      if (Array.isArray(parsedData.history)) {
          newHistory = parsedData.history
            .map((item: any) => ({
                date: item.date,
                rate: item.rate < 5000 ? item.rate * 100 : item.rate
            }))
            .filter((item: any) => item.rate > 100000)
            .sort((a: any, b: any) => new Date(a.date).getTime() - new Date(b.date).getTime())
            .slice(-7);
      }

      const uniqueChunks = Array.from(new Map((response.candidates?.[0]?.groundingMetadata?.groundingChunks as GroundingChunk[] ?? []).filter(item => item.web?.uri).map(item => [item.web!.uri, item])).values());

      setRate(newRate);
      setSources(uniqueChunks);
      if (newHistory.length > 0) {
          setRateHistory(newHistory);
          localStorage.setItem(CACHED_HISTORY_KEY, JSON.stringify(newHistory));
      }

      localStorage.setItem(CACHED_RATE_KEY, JSON.stringify(newRate));
      localStorage.setItem(CACHED_SOURCES_KEY, JSON.stringify(uniqueChunks));

      retryCount.current = 0;
      setError(null);
      setIsLoading(false);

    } catch (e: unknown) {
      console.error(`Fetch error:`, (e as Error).message);
      retryCount.current++;
      if (retryCount.current < MAX_RETRIES) {
        setTimeout(fetchExchangeRate, RETRY_DELAY_MS);
      } else {
        setError('FAILED_AFTER_RETRIES');
        setIsLoading(false);
      }
    }
  }, []);

  const startFetchCycle = useCallback(async (isManualRefresh = false) => {
    if (isManualRefresh) {
      const lastRefreshTime = getInitialState<number>(LAST_REFRESH_KEY);
      if (lastRefreshTime && (Date.now() - lastRefreshTime < REFRESH_COOLDOWN_MS)) {
        updateCooldown(); 
        return;
      }
      localStorage.setItem(LAST_REFRESH_KEY, JSON.stringify(Date.now()));
      updateCooldown();
    }

    retryCount.current = 0;
    setIsLoading(true);
    setError(null);
    await fetchExchangeRate();
  }, [fetchExchangeRate, updateCooldown]);

  useEffect(() => {
    if (!rate) startFetchCycle(false);
    const intervalId = setInterval(() => startFetchCycle(false), FETCH_INTERVAL_MS);
    return () => clearInterval(intervalId);
  }, [startFetchCycle, rate]);

  return {
    rate,
    sources,
    loading: isLoading,
    error,
    refetch: () => startFetchCycle(true),
    rateHistory,
    cooldownSeconds,
  };
};

import React, { useMemo, useState, useEffect, useCallback } from 'react';
import { useExchangeRate } from './hooks/useExchangeRate';
import { Header } from './components/Header';
import { RateDisplay } from './components/RateDisplay';
import { LastUpdated } from './components/LastUpdated';
import { Calculator } from './components/Calculator';
import { translations } from './translations';
import { ThemeToggle } from './components/ThemeToggle';
import { RateDisplaySkeleton } from './components/RateDisplaySkeleton';
import { ComparisonRates } from './components/ComparisonRates';
import { ComparisonRatesSkeleton } from './components/ComparisonRatesSkeleton';
import { useLanguage } from './hooks/useLanguage';
import { LanguageSelector } from './components/LanguageSelector';
import { GroundingSources } from './components/GroundingSources';
import { Dialog } from './components/Dialog';
import { Footer } from './components/Footer';
import { StartupLoader } from './components/StartupLoader';
import { ChatFab } from './components/ChatFab';
import { ChatDialog } from './components/ChatDialog';
import { RateHistoryChart } from './components/RateHistoryChart';
import { RateHistoryChartSkeleton } from './components/RateHistoryChartSkeleton';
import { CurrencyInfoModal } from './components/CurrencyInfoModal';
import { BuyCurrencyModal } from './components/BuyCurrencyModal';

const staticSources = [
    { web: { uri: 'https://t.me/s/iraqborsa', title: 'Iraq Borsa (Telegram)' } },
    { web: { uri: 'https://www.creditbankofiraq.com.iq/personal/currency-rates.html', title: 'Credit Bank of Iraq' } },
    { web: { uri: 'https://www.xe.com/currencyconverter/convert/?Amount=1&From=USD&To=IQD', title: 'XE Currency Converter' } },
];

const ChevronIcon: React.FC<{ className?: string }> = ({ className }) => (
  <svg xmlns="http://www.w3.org/2000/svg" className={className} fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
    <path strokeLinecap="round" strokeLinejoin="round" d="M19 9l-7 7-7-7" />
  </svg>
);

const isLargeScreen = () => {
    if (typeof window === 'undefined') return false;
    return window.matchMedia('(min-width: 1024px)').matches;
};

export default function App(): React.ReactElement {
  const { rate, sources, loading, error, refetch, rateHistory, cooldownSeconds } = useExchangeRate();

  const [isCalculatorOpen, setIsCalculatorOpen] = useState(isLargeScreen());
  const [isChartOpen, setIsChartOpen] = useState(isLargeScreen());
  const [language, setLanguage] = useLanguage();
  const [isAboutOpen, setIsAboutOpen] = useState(false);
  const [isSourcesOpen, setIsSourcesOpen] = useState(false);
  const [isChatOpen, setIsChatOpen] = useState(false);
  const [shareFeedback, setShareFeedback] = useState('');
  const [isManualRefreshing, setIsManualRefreshing] = useState(false);
  const [modalState, setModalState] = useState<{ currency: string | null; view: 'info' | 'buy' }>({ currency: null, view: 'info' });
  const t = translations[language];

  const iqdRateValue = useMemo(() => rate?.iqd ?? 0, [rate]);
  const officialRateValue = useMemo(() => rate?.centralBankRate ?? 1310, [rate]);
  const eurPerUsdValue = useMemo(() => rate?.eurPerUsd ?? 0, [rate]);
  const tryPerUsdValue = useMemo(() => rate?.tryPerUsd ?? 0, [rate]);
  const gbpPerUsdValue = useMemo(() => rate?.gbpPerUsd ?? 0, [rate]);
  const irtPerUsdValue = useMemo(() => rate?.irtPerUsd ?? 0, [rate]);
  const rateForDisplay = useMemo(() => iqdRateValue * 100, [iqdRateValue]);
  const centralBankRateForDisplay = useMemo(() => officialRateValue * 100, [officialRateValue]);

  const allRates = useMemo(() => ({
    IQD: iqdRateValue,
    USD: 1,
    EUR: eurPerUsdValue,
    TRY: tryPerUsdValue,
    GBP: gbpPerUsdValue,
    IRT: irtPerUsdValue,
  }), [iqdRateValue, eurPerUsdValue, tryPerUsdValue, gbpPerUsdValue, irtPerUsdValue]);

  const isInitialLoading = loading && !rate && !error;
  const showFullScreenLoader = isInitialLoading || isManualRefreshing;

  const handleManualRefresh = async () => {
    if (loading || cooldownSeconds > 0) return;
    setIsManualRefreshing(true);
    try {
        await refetch();
    } finally {
        setIsManualRefreshing(false);
    }
  };

  const handleShare = async () => {
    if (!rate) return;
    const shareText = t.shareMessage(Math.floor(rateForDisplay).toLocaleString(), centralBankRateForDisplay.toLocaleString());
    const shareData: ShareData = { title: t.headerTitle, text: shareText };
    const isShareableUrl = window.location.protocol.startsWith('http');
    if (isShareableUrl) shareData.url = window.location.href;

    if (navigator.share) {
      try { await navigator.share(shareData); } catch (err) { if ((err as Error).name !== 'AbortError') console.error('Error sharing:', err); }
    } else {
      try {
        const clipboardText = isShareableUrl ? `${shareText}\n\n${window.location.href}` : shareText;
        await navigator.clipboard.writeText(clipboardText);
        setShareFeedback(t.copiedToClipboard);
        setTimeout(() => setShareFeedback(''), 2000);
      } catch (err) { console.error('Error copying to clipboard:', err); }
    }
  };

  const handleCurrencySelect = (currencyCode: string) => {
    setModalState({ currency: currencyCode, view: 'info' });
  };
  const handleBuyClick = () => setModalState(prev => ({ ...prev, view: 'buy' }));
  const handleCloseModals = () => setModalState({ currency: null, view: 'info' });

  const cityLabels = useMemo(() => ({
    suly: t.sulyName,
    erbil: t.erbilName,
    duhok: t.duhokName,
    regional: t.regionalRatesTitle
  }), [t]);

  return (
    <>
      {showFullScreenLoader && <StartupLoader t={t} />}

      <div className={`min-h-screen w-full transition-filter duration-500 ${showFullScreenLoader ? 'blur-sm' : ''}`}>
        <main className="w-full max-w-7xl mx-auto p-4 sm:p-6 lg:p-8">
          <header className="flex justify-between items-center mb-6 sm:mb-8">
            <div className="flex items-center gap-2">
                <img src="data:image/svg+xml,%3csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 100 100'%3e%3ccircle cx='50' cy='50' r='48' fill='%23FBBF24' stroke='%23B45309' stroke-width='4'/%3e%3ctext x='50' y='60' font-family='Noto Kufi Arabic, sans-serif' font-size='40' font-weight='bold' fill='%23B45309' text-anchor='middle'%3eد.ع%3c/text%3e%3c/svg%3e" alt="DinarLive Logo" className="h-8 w-8 sm:h-10 sm:w-10" />
                <h1 className="text-xl sm:text-2xl font-bold text-gray-800 dark:text-white tracking-tight">{t.appName}</h1>
            </div>
            <div className="flex items-center gap-2 sm:gap-4">
              <ThemeToggle />
              <LanguageSelector currentLang={language} onChangeLang={setLanguage} />
            </div>
          </header>

          {error && (
            <div className="my-6 text-center text-red-500 bg-red-100 dark:bg-red-900/50 p-6 rounded-2xl transition-colors duration-300 animate-fade-in max-w-2xl mx-auto shadow-lg">
                <p className="text-lg font-semibold">{t.errorAfterRetriesTitle}</p>
                <p className="mt-2">{t.errorAfterRetriesMessage}</p>
                <button onClick={() => refetch()} className="mt-6 px-6 py-2.5 rounded-lg bg-sky-600 text-white font-semibold hover:bg-sky-700 active:bg-sky-800 transition-colors focus:outline-none focus:ring-2 focus:ring-sky-500 focus:ring-offset-2 dark:focus:ring-offset-gray-900">
                    {t.retryButton}
                </button>
            </div>
          )}

          {!error && (
            <div className="grid grid-cols-1 lg:grid-cols-5 gap-6 lg:gap-8">
              <div className="lg:col-span-2 space-y-6">
                <div className="bg-white dark:bg-gray-800/50 rounded-2xl shadow-lg p-5 sm:p-6">
                    <Header t={t} />
                    {(loading && !rate) ? (
                        <div className="mt-6 space-y-4">
                            <RateDisplaySkeleton />
                            <RateDisplaySkeleton />
                        </div>
                    ) : rate && (
                        <div className="mt-6 space-y-4 animate-fade-in">
                            <RateDisplay
                                value={rateForDisplay}
                                loading={loading}
                                label={t.marketRateLabel}
                                description={t.marketRateDescription}
                                currency={t.iqdCurrency}
                                cities={rate.cities}
                                cityLabels={cityLabels}
                            />
                            <RateDisplay
                                value={centralBankRateForDisplay}
                                loading={loading}
                                label={t.centralBankRateLabel}
                                description={t.centralBankRateDescription}
                                currency={t.iqdCurrency}
                            />
                        </div>
                    )}
                </div>

                <div className="bg-white dark:bg-gray-800/50 rounded-2xl shadow-lg p-5 sm:p-6">
                    {(loading && !rate) ? (
                        <ComparisonRatesSkeleton />
                    ) : rate && (
                        <ComparisonRates 
                            iqdRate={iqdRateValue}
                            eurRate={eurPerUsdValue}
                            tryRate={tryPerUsdValue}
                            gbpRate={gbpPerUsdValue}
                            irtRate={irtPerUsdValue}
                            t={t}
                            onCurrencySelect={handleCurrencySelect}
                        />
                    )}
                </div>

                {rate && (
                    <div className="bg-white dark:bg-gray-800/50 rounded-2xl shadow-lg p-5 sm:p-6 animate-fade-in">
                        <LastUpdated date={rate.updated} loading={loading} t={t} onRefresh={handleManualRefresh} cooldownSeconds={cooldownSeconds} />
                        <Footer onAboutClick={() => setIsAboutOpen(true)} onSourcesClick={() => setIsSourcesOpen(true)} onShareClick={handleShare} shareFeedback={shareFeedback} t={t} />
                    </div>
                )}
              </div>

              <div className="lg:col-span-3 space-y-6">
                <div className="bg-white dark:bg-gray-800/50 rounded-2xl shadow-lg p-5 sm:p-6">
                    <button onClick={() => setIsChartOpen(prev => !prev)} className="w-full flex items-center justify-between p-2 -m-2 rounded-lg hover:bg-gray-100 dark:hover:bg-gray-700/50 focus:outline-none focus-visible:ring-2 focus-visible:ring-sky-500" aria-expanded={isChartOpen} aria-controls="chart-content">
                        <h2 className="text-lg md:text-xl font-bold text-gray-700 dark:text-gray-200">{t.rateHistoryTitle}</h2>
                        <ChevronIcon className={`w-6 h-6 text-gray-500 dark:text-gray-400 transition-transform duration-300 ${isChartOpen ? 'rotate-180' : ''}`} />
                    </button>
                    <div id="chart-content" className={`transition-all duration-500 ease-in-out overflow-hidden ${isChartOpen ? 'max-h-[500px] opacity-100 mt-4' : 'max-h-0 opacity-0'}`}>
                        {(loading && rateHistory.length === 0) ? <RateHistoryChartSkeleton /> : <RateHistoryChart history={rateHistory} t={t} />}
                    </div>
                </div>

                {rate && (
                    <div className="bg-white dark:bg-gray-800/50 rounded-2xl shadow-lg p-5 sm:p-6 animate-fade-in">
                        <button onClick={() => setIsCalculatorOpen(prev => !prev)} className="w-full flex items-center justify-between p-2 -m-2 rounded-lg hover:bg-gray-100 dark:hover:bg-gray-700/50 focus:outline-none focus-visible:ring-2 focus-visible:ring-sky-500" aria-expanded={isCalculatorOpen} aria-controls="calculator-content">
                            <h2 className="text-lg md:text-xl font-bold text-gray-700 dark:text-gray-200">{t.calculatorTitle}</h2>
                            <ChevronIcon className={`w-6 h-6 text-gray-500 dark:text-gray-400 transition-transform duration-300 ${isCalculatorOpen ? 'rotate-180' : ''}`} />
                        </button>
                        <div id="calculator-content" className={`transition-all duration-500 ease-in-out overflow-hidden ${isCalculatorOpen ? 'max-h-[500px] opacity-100 mt-4' : 'max-h-0 opacity-0'}`}>
                            <Calculator rates={allRates} t={t} onCurrencySelect={handleCurrencySelect} />
                        </div>
                    </div>
                )}
              </div>
            </div>
          )}
        </main>
      </div>

      <Dialog isOpen={isAboutOpen} onClose={() => setIsAboutOpen(false)} title={t.aboutDialogTitle} t={t}>
        <p className="text-sm text-gray-600 dark:text-gray-300 whitespace-pre-line text-center">{t.aboutDialogContent}</p>
      </Dialog>
      <Dialog isOpen={isSourcesOpen} onClose={() => setIsSourcesOpen(false)} title={t.sourcesTitle} t={t}>
        <GroundingSources sources={sources.length > 0 ? sources : staticSources} t={t} />
      </Dialog>
      {modalState.currency && (
        <>
          <CurrencyInfoModal isOpen={modalState.view === 'info'} onClose={handleCloseModals} onBuy={handleBuyClick} currencyCode={modalState.currency} t={t} />
          <BuyCurrencyModal isOpen={modalState.view === 'buy'} onClose={handleCloseModals} currencyCode={modalState.currency} rates={allRates} t={t} />
        </>
      )}
      {!isInitialLoading && (
        <>
            <ChatFab onClick={() => setIsChatOpen(true)} />
            <ChatDialog isOpen={isChatOpen} onClose={() => setIsChatOpen(false)} rate={rate} t={t} />
        </>
      )}
    </>
  );
}

import { useState, useCallback, useRef } from 'react';
import { GoogleGenAI, Chat } from "@google/genai";
import type { ChatMessage, ExchangeRateData, Translation } from '../types';

const formatNumber = (num: number, options?: Intl.NumberFormatOptions) => num.toLocaleString('en-US', options);

export const useChat = (rateData: ExchangeRateData | null, t: Translation) => {
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [isLoading, setIsLoading] = useState(false);
  const chatRef = useRef<Chat | null>(null);

  const createSystemInstruction = useCallback(() => {
    if (!rateData) {
      return `You are a helpful financial assistant for the DinarLive app.
        The app is currently unable to load live exchange rate data.
        Apologize to the user and ask them to try again later. Do not attempt to provide any financial data.`;
    }

    const { iqd, centralBankRate, eurPerUsd, tryPerUsd, gbpPerUsd, irtPerUsd } = rateData;
    const iqdPerEur = eurPerUsd > 0 ? iqd / eurPerUsd : 0;
    const iqdPerTry = tryPerUsd > 0 ? iqd / tryPerUsd : 0;
    const iqdPerGbp = gbpPerUsd > 0 ? iqd / gbpPerUsd : 0;
    const iqdPerIrt = irtPerUsd > 0 ? iqd / irtPerUsd : 0;

    return `You are "Dinar Bot", a helpful AI assistant for the DinarLive app.
      Your purpose is to answer user questions about currency exchange based on the real-time data provided below.
      - Be friendly, concise, and helpful.
      - Answer in the same language as the user's question.
      - Use the provided data to perform calculations if asked. Do not use any external knowledge for rates.
      - When providing a rate, always mention it's the current market rate from the app.
      - The user's locale is '${t.appName === "DinarLive" ? "en" : t.appName === "دينار لايف" ? "ar" : "ku"}'. Format numbers appropriately but keep currency symbols like USD, IQD, EUR, TRY, GBP, IRT.

      CURRENT REAL-TIME DATA:
      - Market Rate (100 USD to IQD): ${formatNumber(iqd * 100, {maximumFractionDigits: 0})} IQD
      - Central Bank Rate (100 USD to IQD): ${formatNumber(centralBankRate * 100, {maximumFractionDigits: 0})} IQD
      - 1 USD = ${formatNumber(iqd, {maximumFractionDigits: 2})} IQD
      - 1 EUR = ${formatNumber(iqdPerEur, {maximumFractionDigits: 2})} IQD
      - 1 TRY = ${formatNumber(iqdPerTry, {maximumFractionDigits: 2})} IQD
      - 1 GBP = ${formatNumber(iqdPerGbp, {maximumFractionDigits: 2})} IQD
      - 1 IRT = ${formatNumber(iqdPerIrt, {maximumFractionDigits: 2})} IQD
    `;
  }, [rateData, t]);

  const sendMessage = useCallback(async (message: string) => {
    if (!message.trim()) return;

    setIsLoading(true);
    const userMessage: ChatMessage = { role: 'user', content: message };
    setMessages(prev => [...prev, userMessage]);

    try {
      if (!chatRef.current) {
        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
        chatRef.current = ai.chats.create({
          model: 'gemini-3-flash-preview',
          config: {
            systemInstruction: createSystemInstruction(),
          },
        });
      }

      const stream = await chatRef.current.sendMessageStream({ message });

      let modelResponse = '';
      setMessages(prev => [...prev, { role: 'model', content: '' }]);

      for await (const chunk of stream) {
        modelResponse += chunk.text;
        setMessages(prev => {
          const newMessages = [...prev];
          newMessages[newMessages.length - 1].content = modelResponse;
          return newMessages;
        });
      }
    } catch (error) {
      console.error("Error sending message to AI:", error);
      const errorMessage: ChatMessage = { role: 'model', content: "Sorry, I couldn't process that. Please try again." };
      setMessages(prev => [...prev, errorMessage]);
    } finally {
      setIsLoading(false);
    }
  }, [createSystemInstruction]);

  return { messages, isLoading, sendMessage };
};

import { useState, useEffect, useCallback, useRef } from 'react';
import type { ExchangeRateData, GroundingChunk, ExchangeRateErrorType, RateHistoryEntry } from '../types';
import { GoogleGenAI } from "@google/genai";

const FETCH_INTERVAL_MS = 2 * 60 * 60 * 1000; // 2 hours
const REFRESH_COOLDOWN_MS = 5 * 60 * 1000; // 5 minutes
const MAX_RETRIES = 3;
const RETRY_DELAY_MS = 2000;

const CACHED_RATE_KEY = 'dinarLive_cachedRate';
const CACHED_SOURCES_KEY = 'dinarLive_cachedSources';
const CACHED_HISTORY_KEY = 'dinarLive_cachedHistory';
const LAST_REFRESH_KEY = 'dinarLive_lastRefresh';

const getInitialState = <T,>(key: string): T | null => {
    try {
        const item = localStorage.getItem(key);
        return item ? JSON.parse(item) : null;
    } catch (error) {
        console.warn(`Error reading localStorage key “${key}”:`, error);
        return null;
    }
};

export const useExchangeRate = () => {
  const [rate, setRate] = useState<ExchangeRateData | null>(() => getInitialState<ExchangeRateData>(CACHED_RATE_KEY));
  const [sources, setSources] = useState<GroundingChunk[]>(() => getInitialState<GroundingChunk[]>(CACHED_SOURCES_KEY) || []);
  const [rateHistory, setRateHistory] = useState<RateHistoryEntry[]>(() => getInitialState<RateHistoryEntry[]>(CACHED_HISTORY_KEY) || []);
  const [isLoading, setIsLoading] = useState<boolean>(!rate);
  const [error, setError] = useState<ExchangeRateErrorType>(null);
  const [cooldownSeconds, setCooldownSeconds] = useState(0);

  const retryCount = useRef(0);
  const cooldownTimerRef = useRef<number | null>(null);

  const updateCooldown = useCallback(() => {
    const lastRefreshTime = getInitialState<number>(LAST_REFRESH_KEY);
    if (!lastRefreshTime) {
      setCooldownSeconds(0);
      return;
    }
    const timeSinceLastRefresh = Date.now() - lastRefreshTime;
    const remainingCooldown = REFRESH_COOLDOWN_MS - timeSinceLastRefresh;

    if (remainingCooldown > 0) {
      setCooldownSeconds(Math.ceil(remainingCooldown / 1000));
    } else {
      setCooldownSeconds(0);
    }
  }, []);

  useEffect(() => {
    updateCooldown();
    cooldownTimerRef.current = window.setInterval(updateCooldown, 1000);
    return () => {
      if (cooldownTimerRef.current) clearInterval(cooldownTimerRef.current);
    };
  }, [updateCooldown]);

  const fetchExchangeRate = useCallback(async () => {
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

      const prompt = `
        **URGENT EXTRACTION TASK**
        You must fetch the latest exchange rates for the Iraqi Dinar (IQD) from these TWO specific sources. Do NOT use cached or generic data.

        **1. MARKET RATES (Telegram):**
        Source: https://t.me/s/iraqborsa
        Message Format: "*100$=145,950 سلێمانی پێنجی*" or "*100$=145,850 هەولێر پێنجی*"
        Action: Find the MOST RECENT message for each city.
        - **Sulaymaniyah (سلێمانی)**: Get value next to "سلێمانی پێنجی".
        - **Erbil (هەولێر)**: Get value next to "هەولێر پێنجی".
        - **Duhok (دهۆک)**: Get value next to "دهۆک پێنجی".

        **2. OFFICIAL RATE (Credit Bank):**
        Source: https://www.creditbankofiraq.com.iq/personal/currency-rates.html
        Action: Find "US Dollar" and its corresponding "Sell Rate".
        Expected result: near 1320 or 132,000.

        **3. OTHER RATES:**
        - Get global USD to EUR, TRY, GBP, and IRT (Toman) rates.
        - Get 7-day Sulaymaniyah price history (USD to IQD).

        **REQUIRED JSON OUTPUT:**
        {
          "current": {
            "suly100Usd": number,
            "erbil100Usd": number,
            "duhok100Usd": number,
            "officialRate": number,
            "eurPerUsd": number,
            "tryPerUsd": number,
            "gbpPerUsd": number,
            "irtPerUsd": number
          },
          "history": [
            { "date": "YYYY-MM-DD", "rate": number }
          ]
        }
      `;

      const response = await ai.models.generateContent({
        model: 'gemini-3-pro-preview',
        contents: prompt,
        config: {
          tools: [{ googleSearch: {} }],
        },
      });

      const rawText = response.text;
      const jsonMatch = rawText.match(/\{[\s\S]*\}/);

      if (!jsonMatch) throw new Error("AI failed to return valid JSON");

      const parsedData = JSON.parse(jsonMatch[0]);

      const suly = parsedData.current?.suly100Usd || 0;
      const erbil = parsedData.current?.erbil100Usd || 0;
      const duhok = parsedData.current?.duhok100Usd || 0;
      const official = parsedData.current?.officialRate || 1320;

      // Validation check - if suly is suspiciously generic or zero, fail and retry
      if (suly < 100000 || suly === 141300) {
        throw new Error("Extracted rate is either static fallback or invalid");
      }

      const normalizedOfficial = official > 10000 ? official / 100 : official;

      const newRate: ExchangeRateData = {
        iqd: suly / 100,
        centralBankRate: normalizedOfficial,
        cities: {
            sulaymaniyah: suly,
            erbil: erbil || suly,
            duhok: duhok || suly,
        },
        eurPerUsd: parsedData.current.eurPerUsd || 0,
        tryPerUsd: parsedData.current.tryPerUsd || 0,
        gbpPerUsd: parsedData.current.gbpPerUsd || 0,
        irtPerUsd: parsedData.current.irtPerUsd || 0,
        updated: new Date().toISOString(),
      };

      let newHistory: RateHistoryEntry[] = [];
      if (Array.isArray(parsedData.history)) {
          newHistory = parsedData.history
            .map((item: any) => ({
                date: item.date,
                rate: item.rate < 5000 ? item.rate * 100 : item.rate
            }))
            .filter((item: any) => item.rate > 100000)
            .sort((a: any, b: any) => new Date(a.date).getTime() - new Date(b.date).getTime())
            .slice(-7);
      }

      const groundingChunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks as GroundingChunk[] ?? [];
      const uniqueChunks = Array.from(new Map(groundingChunks.filter(item => item.web?.uri).map(item => [item.web!.uri, item])).values());

      setRate(newRate);
      setSources(uniqueChunks);
      if (newHistory.length > 0) {
          setRateHistory(newHistory);
          localStorage.setItem(CACHED_HISTORY_KEY, JSON.stringify(newHistory));
      }

      localStorage.setItem(CACHED_RATE_KEY, JSON.stringify(newRate));
      localStorage.setItem(CACHED_SOURCES_KEY, JSON.stringify(uniqueChunks));

      retryCount.current = 0;
      setError(null);
      setIsLoading(false);

    } catch (e: unknown) {
      console.error(`Fetch failed:`, (e as Error).message);
      retryCount.current++;
      if (retryCount.current < MAX_RETRIES) {
        setTimeout(fetchExchangeRate, RETRY_DELAY_MS);
      } else {
        setError('FAILED_AFTER_RETRIES');
        setIsLoading(false);
      }
    }
  }, []);

  const startFetchCycle = useCallback(async (isManualRefresh = false) => {
    if (isManualRefresh) {
      const lastRefreshTime = getInitialState<number>(LAST_REFRESH_KEY);
      if (lastRefreshTime && (Date.now() - lastRefreshTime < REFRESH_COOLDOWN_MS)) {
        updateCooldown(); 
        return;
      }
      localStorage.setItem(LAST_REFRESH_KEY, JSON.stringify(Date.now()));
      updateCooldown();
    }

    retryCount.current = 0;
    setIsLoading(true);
    setError(null);
    await fetchExchangeRate();
  }, [fetchExchangeRate, updateCooldown]);

  useEffect(() => {
    if (!rate) startFetchCycle(false);
    const intervalId = setInterval(() => startFetchCycle(false), FETCH_INTERVAL_MS);
    return () => clearInterval(intervalId);
  }, [startFetchCycle, rate]);

  return {
    rate,
    sources,
    loading: isLoading,
    error,
    refetch: () => startFetchCycle(true),
    rateHistory,
    cooldownSeconds,
  };
};

import React, { useState, useMemo } from 'react';
import type { Translation } from '../types';

interface CalculatorProps {
  rates: {
    [key: string]: number;
  };
  t: Translation;
  onCurrencySelect: (currencyCode: string) => void;
}

const SwapIcon: React.FC<{ className?: string; style?: React.CSSProperties }> = ({ className, style }) => (
  <svg xmlns="http://www.w3.org/2000/svg" className={className} style={style} fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2.5}>
    <path strokeLinecap="round" strokeLinejoin="round" d="M7 16V4m0 0L3 8m4-4l4 4m6 0v12m0 0l4-4m-4 4l-4-4" />
  </svg>
);

const Tooltip: React.FC<{ text: string; children: React.ReactNode; className?: string }> = ({ text, children, className }) => {
  return (
    <div className={`group relative ${className}`}>
      {children}
      <div className="absolute bottom-full left-1/2 -translate-x-1/2 mb-2 px-2 py-1 bg-gray-900 dark:bg-gray-100 text-white dark:text-black text-[10px] sm:text-xs font-semibold rounded-md shadow-lg whitespace-nowrap opacity-0 group-hover:opacity-100 transition-opacity pointer-events-none z-30">
        {text}
      </div>
    </div>
  );
};

export const Calculator: React.FC<CalculatorProps> = ({ rates, t, onCurrencySelect }) => {
  const [amount, setAmount] = useState('');
  const [fromCurrency, setFromCurrency] = useState('USD');
  const [toCurrency, setToCurrency] = useState('IQD');
  const [rotation, setRotation] = useState(0);
  const [isSwapping, setIsSwapping] = useState(false);

  const currencies = useMemo(() => [
    { code: 'USD', name: t.usd },
    { code: 'IQD', name: t.iqd },
    { code: 'EUR', name: t.eur },
    { code: 'TRY', name: t.try },
    { code: 'GBP', name: t.gbp },
    { code: 'IRT', name: t.irt },
  ], [t]);

  const currencyTooltips: { [key: string]: keyof Translation } = useMemo(() => ({
    USD: 'usdTooltip',
    IQD: 'iqdTooltip',
    EUR: 'eurTooltip',
    TRY: 'tryTooltip',
    GBP: 'gbpTooltip',
    IRT: 'irtTooltip',
  }), []);

  const directRate = useMemo(() => {
    const fromRate = rates[fromCurrency];
    const toRate = rates[toCurrency];
    if (typeof fromRate !== 'number' || typeof toRate !== 'number' || fromRate <= 0) {
      return 0;
    }
    return toRate / fromRate;
  }, [fromCurrency, toCurrency, rates]);

  const calculatedResult = useMemo(() => {
    const numericAmount = parseFloat(amount);
    if (isNaN(numericAmount) || numericAmount <= 0 || directRate <= 0) {
      return '0';
    }
    const result = numericAmount * directRate;
    const formatOptions: Intl.NumberFormatOptions = {};
    if (toCurrency === 'IQD' || toCurrency === 'IRT') {
        formatOptions.maximumFractionDigits = 0;
    } else {
        formatOptions.minimumFractionDigits = 2;
        formatOptions.maximumFractionDigits = 2;
    }
    return result.toLocaleString('en-US', formatOptions);
  }, [amount, toCurrency, directRate]);

  const handleSwap = () => {
    setRotation(prev => prev + 180);
    setIsSwapping(true);
    const tempFrom = fromCurrency;
    setFromCurrency(toCurrency);
    setToCurrency(tempFrom);
    setTimeout(() => setIsSwapping(false), 300);
  };

  const selectorBaseClass = "w-full appearance-none border rounded-xl py-2.5 sm:py-3 px-2 sm:px-4 text-center font-bold text-sm sm:text-base cursor-pointer focus:outline-none focus:ring-2 focus:ring-sky-500 transition-all duration-300 shadow-sm";
  const selectorStateClass = isSwapping 
    ? "bg-sky-50 dark:bg-sky-900/40 border-sky-300 dark:border-sky-600 text-sky-700 dark:text-sky-300 transform scale-105 ring-2 ring-sky-200 dark:ring-sky-800" 
    : "bg-gray-100 dark:bg-gray-700 border-transparent hover:border-gray-300 dark:hover:border-gray-500 text-gray-800 dark:text-white";

  return (
    <div className="flex flex-col gap-5 sm:gap-6">
      {/* Amount Input Section */}
      <div className="relative">
        <label htmlFor="amount" className="block text-xs sm:text-sm font-semibold text-gray-500 dark:text-gray-400 mb-1.5">{t.amount}</label>
        <div className="relative">
           <input
            id="amount"
            type="number"
            inputMode="decimal"
            value={amount}
            onChange={(e) => setAmount(e.target.value)}
            placeholder={t.amountPlaceholder}
            className="w-full p-3 sm:p-4 pl-4 pr-12 text-xl sm:text-2xl font-bold bg-white dark:bg-gray-800 border-2 border-gray-200 dark:border-gray-600 rounded-xl text-gray-900 dark:text-white focus:ring-2 focus:ring-sky-500 focus:border-sky-500 outline-none transition-all placeholder:text-gray-300 dark:placeholder:text-gray-600 shadow-sm"
            dir="ltr"
          />
        </div>
      </div>

      {/* Currency Selection Grid */}
      <div className="relative grid grid-cols-[1fr_auto_1fr] items-end gap-2 sm:gap-4">
        {/* FROM Currency */}
        <div className="flex flex-col gap-1.5 min-w-0">
          <label className="text-[10px] sm:text-sm font-semibold text-gray-500 dark:text-gray-400">{t.from}</label>
          <Tooltip text={t[currencyTooltips[fromCurrency]]} className="w-full">
            <div className="relative">
              <select 
                value={fromCurrency} 
                onChange={e => setFromCurrency(e.target.value)} 
                className={`${selectorBaseClass} ${selectorStateClass}`}
              >
                {currencies.map(c => <option key={c.code} value={c.code} className="text-gray-900 dark:text-white bg-white dark:bg-gray-800">{c.code}</option>)}
              </select>
            </div>
          </Tooltip>
        </div>

        {/* Swap Button */}
        <div className="flex flex-col justify-end pb-0.5">
            <button 
                onClick={handleSwap} 
                className="p-2.5 sm:p-3 bg-sky-100 dark:bg-sky-900/30 text-sky-600 dark:text-sky-400 rounded-full hover:bg-sky-200 dark:hover:bg-sky-800 active:bg-sky-300 dark:active:bg-sky-700 transition-all shadow-md focus:outline-none focus:ring-2 focus:ring-sky-500 z-10"
                aria-label="Swap currencies"
            >
                <SwapIcon 
                  className="w-5 h-5 sm:w-6 sm:h-6 transition-transform duration-500 ease-in-out" 
                  style={{ transform: `rotate(${rotation}deg)` }}
                />
            </button>
        </div>

        {/* TO Currency */}
        <div className="flex flex-col gap-1.5 min-w-0">
          <label className="text-[10px] sm:text-sm font-semibold text-gray-500 dark:text-gray-400">{t.to}</label>
          <Tooltip text={t[currencyTooltips[toCurrency]]} className="w-full">
            <div className="relative">
              <select 
                value={toCurrency} 
                onChange={e => setToCurrency(e.target.value)} 
                className={`${selectorBaseClass} ${selectorStateClass}`}
              >
                {currencies.map(c => <option key={c.code} value={c.code} className="text-gray-900 dark:text-white bg-white dark:bg-gray-800">{c.code}</option>)}
              </select>
            </div>
          </Tooltip>
        </div>
      </div>

      {/* Result Card */}
      <Tooltip text={t.resultTooltip} className="w-full">
        <div className="bg-gradient-to-br from-green-50 to-emerald-50 dark:from-green-900/10 dark:to-emerald-900/10 border border-green-100 dark:border-green-800/50 rounded-2xl p-5 sm:p-6 text-center shadow-sm">
          <p className="text-[10px] sm:text-sm font-medium text-green-600 dark:text-green-400 mb-2 uppercase tracking-wide">{t.result}</p>
          <p className="text-2xl sm:text-4xl font-extrabold font-mono text-green-800 dark:text-green-100 break-words leading-tight" dir="ltr">
             {calculatedResult}
          </p>
          {directRate > 0 && fromCurrency !== toCurrency && (
              <div className="mt-3 inline-block bg-white/50 dark:bg-black/30 px-3 py-1 rounded-full border border-green-100 dark:border-green-800/30">
                  <p className="text-[10px] sm:text-xs text-green-700 dark:text-green-300 font-mono" dir="ltr">
                    1{' '}
                    <button 
                        onClick={() => onCurrencySelect(fromCurrency)}
                        className="font-bold hover:underline cursor-pointer focus:outline-none focus:text-green-800 dark:focus:text-green-200"
                    >
                        {fromCurrency}
                    </button>
                    {' '}≈{' '}
                    {directRate.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 4 })}
                    {' '}
                    <button 
                        onClick={() => onCurrencySelect(toCurrency)}
                        className="font-bold hover:underline cursor-pointer focus:outline-none focus:text-green-800 dark:focus:text-green-200"
                    >
                        {toCurrency}
                    </button>
                  </p>
              </div>
          )}
        </div>
      </Tooltip>
    </div>
  );
};

import React, { useMemo, useState, useRef, useCallback } from 'react';
import type { RateHistoryEntry, Translation } from '../types';

interface RateHistoryChartProps {
  history: RateHistoryEntry[];
  t: Translation;
}

const SVG_WIDTH = 380;
const SVG_HEIGHT = 180;
const PADDING = { top: 20, right: 20, bottom: 30, left: 55 };
const Y_AXIS_TICKS = 5;

export const RateHistoryChart: React.FC<RateHistoryChartProps> = ({ history, t }) => {
    const [tooltip, setTooltip] = useState<{ x: number; y: number; date: string; rate: number } | null>(null);
    const svgRef = useRef<SVGSVGElement>(null);

    const processedData = useMemo(() => {
        if (!history || history.length < 2) return null;
        return history
            .map(d => ({ ...d, date: new Date(d.date) }))
            .sort((a, b) => a.date.getTime() - b.date.getTime());
    }, [history]);

    const scales = useMemo(() => {
        if (!processedData) return null;
        const rates = processedData.map(d => d.rate);
        const dates = processedData.map(d => d.date.getTime());
        const minRate = Math.min(...rates);
        const maxRate = Math.max(...rates);
        const ratePadding = (maxRate - minRate) * 0.1 || 100;
        return {
            minRate: minRate - ratePadding,
            maxRate: maxRate + ratePadding,
            minDate: Math.min(...dates),
            maxDate: Math.max(...dates),
        };
    }, [processedData]);

    const { pathD, areaPathD, yAxisLabels, xAxisLabels } = useMemo(() => {
        if (!processedData || !scales) return { pathD: '', areaPathD: '', yAxisLabels: [], xAxisLabels: [] };
        const { minRate, maxRate, minDate, maxDate } = scales;
        const chartWidth = SVG_WIDTH - PADDING.left - PADDING.right;
        const chartHeight = SVG_HEIGHT - PADDING.top - PADDING.bottom;
        const getX = (date: Date) => PADDING.left + ((date.getTime() - minDate) / (maxDate - minDate)) * chartWidth;
        const getY = (rate: number) => PADDING.top + chartHeight - ((rate - minRate) / (maxRate - minRate)) * chartHeight;

        let path = '';
        processedData.forEach((d, i) => {
            const command = i === 0 ? 'M' : 'L';
            path += `${command}${getX(d.date)},${getY(d.rate)} `;
        });
        const areaPath = `${path} V${SVG_HEIGHT - PADDING.bottom} H${PADDING.left} Z`;
        const yLabels = [];
        for (let i = 0; i < Y_AXIS_TICKS; i++) {
            const rate = minRate + (i / (Y_AXIS_TICKS - 1)) * (maxRate - minRate);
            yLabels.push({
                y: getY(rate),
                label: Math.round(rate / 100) * 100,
            });
        }
        const xLabels = [];
        const first = processedData[0];
        const last = processedData[processedData.length - 1];
        if (first) xLabels.push({ x: getX(first.date), label: first.date.toLocaleDateString(undefined, { month: 'short', day: 'numeric' }) });
        if (last && last.date.getDate() !== first.date.getDate()) xLabels.push({ x: getX(last.date), label: last.date.toLocaleDateString(undefined, { month: 'short', day: 'numeric' }) });
        return { pathD: path, areaPathD: areaPath, yAxisLabels: yLabels, xAxisLabels: xLabels };
    }, [processedData, scales]);

    const handleMouseMove = useCallback((event: React.MouseEvent<SVGSVGElement>) => {
        if (!processedData || !scales || !svgRef.current) return;
        const svgRect = svgRef.current.getBoundingClientRect();
        const mouseXInSvg = ((event.clientX - svgRect.left) / svgRect.width) * SVG_WIDTH;

        const chartWidth = SVG_WIDTH - PADDING.left - PADDING.right;
        const { minDate, maxDate, minRate, maxRate } = scales;
        const getX = (date: Date) => PADDING.left + ((date.getTime() - minDate) / (maxDate - minDate)) * chartWidth;
        const getY = (rate: number) => PADDING.top + (SVG_HEIGHT - PADDING.top - PADDING.bottom) - ((rate - minRate) / (maxRate - minRate)) * (SVG_HEIGHT - PADDING.top - PADDING.bottom);

        let closestPoint = processedData[0];
        let minDistance = Infinity;
        for (const point of processedData) {
            const pointX = getX(point.date);
            const distance = Math.abs(pointX - mouseXInSvg);
            if (distance < minDistance) {
                minDistance = distance;
                closestPoint = point;
            }
        }
        setTooltip({
            x: getX(closestPoint.date),
            y: getY(closestPoint.rate),
            date: closestPoint.date.toLocaleString(undefined, { dateStyle: 'medium', timeStyle: 'short' }),
            rate: closestPoint.rate
        });
    }, [processedData, scales]);

    if (!processedData) {
        return <p className="text-center text-sm text-gray-500 dark:text-gray-400 py-4">{t.noHistoryData}</p>;
    }

    // Determine tooltip position offset to prevent cutting off
    const getTooltipStyles = () => {
        if (!tooltip) return {};
        const isLeftSide = tooltip.x < SVG_WIDTH / 2;
        const isNearTop = tooltip.y < 80;

        return {
            transform: `translate(${isLeftSide ? tooltip.x + 10 : tooltip.x - 130}px, ${isNearTop ? tooltip.y + 20 : tooltip.y - 75}px)`,
            zIndex: 50
        };
    };

    return (
        <div className="relative w-full overflow-visible">
            <svg 
                ref={svgRef} 
                viewBox={`0 0 ${SVG_WIDTH} ${SVG_HEIGHT}`} 
                onMouseMove={handleMouseMove} 
                onMouseLeave={() => setTooltip(null)} 
                className="w-full h-auto block"
                style={{ touchAction: 'none' }}
            >
                <defs>
                    <linearGradient id="areaGradient" x1="0" y1="0" x2="0" y2="1">
                        <stop offset="0%" className="text-sky-400 dark:text-sky-500" stopOpacity={0.4} />
                        <stop offset="100%" className="text-sky-400 dark:text-sky-500" stopOpacity={0} />
                    </linearGradient>
                </defs>

                {/* Grid Lines */}
                {yAxisLabels.map(({ y, label }) => (
                    <g key={label}>
                        <line x1={PADDING.left} y1={y} x2={SVG_WIDTH - PADDING.right} y2={y} className="stroke-gray-200 dark:stroke-gray-700" strokeWidth="1" strokeDasharray="2,2" />
                        <text x={PADDING.left - 8} y={y + 4} textAnchor="end" className="text-[10px] fill-gray-500 dark:fill-gray-400">{label.toLocaleString()}</text>
                    </g>
                ))}

                 {/* X-Axis Labels */}
                {xAxisLabels.map(({ x, label }) => (
                    <text key={label} x={x} y={SVG_HEIGHT - PADDING.bottom + 15} textAnchor="middle" className="text-[10px] fill-gray-500 dark:fill-gray-400">{label}</text>
                ))}

                {/* Area Path */}
                <path d={areaPathD} fill="url(#areaGradient)" />

                {/* Line Path */}
                <path d={pathD} fill="none" className="stroke-sky-500 dark:stroke-sky-400" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round" />

                {/* Hover elements */}
                {tooltip && (
                    <g>
                        <line x1={tooltip.x} y1={PADDING.top} x2={tooltip.x} y2={SVG_HEIGHT - PADDING.bottom} className="stroke-gray-300 dark:stroke-gray-600" strokeWidth="1" strokeDasharray="3,3" />
                        <circle cx={tooltip.x} cy={tooltip.y} r="5" className="fill-sky-500 stroke-white dark:stroke-gray-800" strokeWidth="2" />
                    </g>
                )}
            </svg>

            {tooltip && (
                 <div 
                    className="absolute top-0 left-0 p-2 text-center bg-gray-900/95 backdrop-blur-sm text-white rounded-lg shadow-xl pointer-events-none transition-transform duration-75 ease-out"
                    style={getTooltipStyles()}
                >
                    <p className="text-xs font-bold font-mono tracking-tighter">{tooltip.rate.toLocaleString()}</p>
                    <p className="text-[9px] opacity-70 whitespace-nowrap">{tooltip.date}</p>
                </div>
            )}
        </div>
    );
};

import React, { useState, useEffect, useRef } from 'react';
import type { Translation, ExchangeRateData } from '../types';
import { useChat } from '../hooks/useChat';
import { SendIcon } from './icons/SendIcon';

interface ChatDialogProps {
  isOpen: boolean;
  onClose: () => void;
  rate: ExchangeRateData | null;
  t: Translation;
}

const CloseIcon: React.FC = () => (
    <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
        <path strokeLinecap="round" strokeLinejoin="round" d="M6 18L18 6M6 6l12 12" />
    </svg>
);

const BotIcon: React.FC = () => (
    <div className="w-8 h-8 rounded-full bg-sky-500 flex items-center justify-center text-white font-bold text-xs flex-shrink-0">
        د.ع
    </div>
);

const UserIcon: React.FC = () => (
    <div className="w-8 h-8 rounded-full bg-gray-300 dark:bg-gray-600 flex items-center justify-center text-gray-600 dark:text-gray-300 flex-shrink-0">
        <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" viewBox="0 0 20 20" fill="currentColor">
            <path fillRule="evenodd" d="M10 9a3 3 0 100-6 3 3 0 000 6zm-7 9a7 7 0 1114 0H3z" clipRule="evenodd" />
        </svg>
    </div>
);

export const ChatDialog: React.FC<ChatDialogProps> = ({ isOpen, onClose, rate, t }) => {
  const [inputValue, setInputValue] = useState('');
  const { messages, isLoading, sendMessage } = useChat(rate, t);
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const textAreaRef = useRef<HTMLTextAreaElement>(null);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  useEffect(scrollToBottom, [messages]);

  useEffect(() => {
    if (isOpen) {
        setTimeout(() => textAreaRef.current?.focus(), 100);
    }
  }, [isOpen]);

  const handleSend = () => {
    if (inputValue.trim() && !isLoading) {
      sendMessage(inputValue);
      setInputValue('');
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent<HTMLTextAreaElement>) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSend();
    }
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-[60] bg-black/40 backdrop-blur-[2px] animate-fade-in flex flex-col items-center justify-center" aria-modal="true" role="dialog">
      <div className="flex flex-col h-[100dvh] w-full max-w-2xl bg-white dark:bg-black sm:h-[80vh] sm:rounded-2xl shadow-2xl animate-slide-up overflow-hidden">

        {/* Header */}
        <header className="flex items-center justify-between px-4 py-3 border-b border-gray-100 dark:border-gray-800 flex-shrink-0 bg-white dark:bg-black">
          <div className="flex items-center gap-2">
            <div className="p-1 bg-sky-100 dark:bg-sky-900/30 rounded-lg">
                <BotIcon />
            </div>
            <h2 className="text-base font-bold text-gray-800 dark:text-gray-100">{t.chatTitle}</h2>
          </div>
          <button onClick={onClose} className="p-2 rounded-full text-gray-500 hover:bg-gray-100 dark:text-gray-400 dark:hover:bg-gray-800 transition-colors" aria-label={t.closeButton}>
            <CloseIcon />
          </button>
        </header>

        {/* Messages */}
        <div className="flex-1 overflow-y-auto p-4 space-y-4 bg-gray-50/50 dark:bg-gray-900/10">
          {messages.length === 0 ? (
            <div className="h-full flex flex-col items-center justify-center text-center opacity-60 px-8">
              <BotIcon />
              <p className="mt-4 text-sm font-medium text-gray-500 dark:text-gray-400 leading-relaxed">{t.chatWelcomeMessage}</p>
            </div>
          ) : (
            messages.map((msg, index) => (
              <div key={index} className={`flex items-start gap-2 sm:gap-3 ${msg.role === 'user' ? 'justify-end' : ''}`}>
                {msg.role === 'model' && <BotIcon />}
                <div className={`max-w-[85%] sm:max-w-[75%] p-3 rounded-2xl text-sm leading-relaxed whitespace-pre-wrap ${msg.role === 'user' ? 'bg-sky-600 text-white rounded-br-none' : 'bg-white dark:bg-gray-800 text-gray-800 dark:text-gray-200 shadow-sm rounded-bl-none border border-gray-100 dark:border-gray-700/50'}`}>
                  {msg.content}
                </div>
                {msg.role === 'user' && <UserIcon />}
              </div>
            ))
          )}
          {isLoading && messages[messages.length-1]?.role === 'user' && (
            <div className="flex items-start gap-3">
                <BotIcon />
                <div className="p-3 rounded-2xl bg-white dark:bg-gray-800 text-gray-400 rounded-bl-none shadow-sm border border-gray-100 dark:border-gray-700/50">
                    <div className="flex gap-1">
                        <span className="w-1 h-1 rounded-full bg-current animate-bounce [animation-delay:-0.3s]"></span>
                        <span className="w-1 h-1 rounded-full bg-current animate-bounce [animation-delay:-0.15s]"></span>
                        <span className="w-1 h-1 rounded-full bg-current animate-bounce"></span>
                    </div>
                </div>
            </div>
          )}
          <div ref={messagesEndRef} />
        </div>

        {/* Input */}
        <footer className="p-3 sm:p-4 border-t border-gray-100 dark:border-gray-800 bg-white dark:bg-black flex-shrink-0">
            <div className="flex items-end gap-2 max-w-full">
                <textarea
                    ref={textAreaRef}
                    value={inputValue}
                    onChange={(e) => setInputValue(e.target.value)}
                    onKeyDown={handleKeyDown}
                    placeholder={t.chatInputPlaceholder}
                    rows={1}
                    className="flex-1 p-3 text-sm bg-gray-100 dark:bg-gray-800 border border-transparent rounded-xl resize-none focus:outline-none focus:ring-2 focus:ring-sky-500 transition-all dark:text-white"
                    style={{ maxHeight: '120px' }}
                />
                <button
                    onClick={handleSend}
                    disabled={isLoading || !inputValue.trim()}
                    className="p-3 rounded-xl bg-sky-600 text-white hover:bg-sky-700 disabled:opacity-40 disabled:cursor-not-allowed transition-all shadow-lg active:scale-95"
                    aria-label={t.sendButton}
                >
                    <SendIcon />
                </button>
            </div>
        </footer>
      </div>
      <style>{`
        @keyframes fadeIn { from { opacity: 0; } to { opacity: 1; } }
        .animate-fade-in { animation: fadeIn 0.2s ease-out forwards; }
        @keyframes slideUp { from { transform: translateY(20px); opacity: 0; } to { transform: translateY(0); opacity: 1; } }
        .animate-slide-up { animation: slideUp 0.3s cubic-bezier(0.25, 1, 0.5, 1) forwards; }
      `}</style>
    </div>
  );
};

import { useState, useEffect } from 'react';

type Theme = 'light' | 'dark';

export const useTheme = () => {
  // Initialize state from localStorage only. Default to 'light'.
  const [theme, setTheme] = useState<Theme>(() => {
    if (typeof window !== 'undefined') {
      const stored = localStorage.getItem('theme');
      return stored === 'dark' ? 'dark' : 'light';
    }
    return 'light';
  });

  useEffect(() => {
    const root = document.documentElement;
    // Explicitly manage the class list to ensure consistency
    if (theme === 'dark') {
      root.classList.add('dark');
    } else {
      root.classList.remove('dark');
    }
    localStorage.setItem('theme', theme);
  }, [theme]);

  const toggleTheme = () => {
    setTheme(prev => prev === 'light' ? 'dark' : 'light');
  };

  return { theme, toggleTheme };
};

import React, { useState, useMemo } from 'react';
import type { Translation } from '../types';

interface CalculatorProps {
  rates: {
    [key: string]: number;
  };
  t: Translation;
  onCurrencySelect: (currencyCode: string) => void;
}

const SwapIcon: React.FC<{ className?: string; style?: React.CSSProperties }> = ({ className, style }) => (
  <svg xmlns="http://www.w3.org/2000/svg" className={className} style={style} fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2.5}>
