import { useState, useEffect } from 'react';

type Theme = 'light' | 'dark';

export const useTheme = () => {
  // Initialize state from localStorage. Default to 'dark' if not set (or user preference), 
  // but based on your request, we default to 'light' or whatever is in storage.
  const [theme, setTheme] = useState<Theme>(() => {
    if (typeof window !== 'undefined') {
      const stored = localStorage.getItem('theme');
      return stored === 'light' ? 'light' : 'dark'; // Default to dark if nothing stored
    }
    return 'dark';
  });

  useEffect(() => {
    const root = document.documentElement;
    // Remove both to ensure clean state, then add current
    root.classList.remove('light', 'dark');
    root.classList.add(theme);
    localStorage.setItem('theme', theme);
  }, [theme]);

  const toggleTheme = () => {
    setTheme(prev => prev === 'light' ? 'dark' : 'light');
  };

  return { theme, toggleTheme };
};

