import React, { useState, useEffect } from 'react';
import type { Translation } from '../types';

interface LastUpdatedProps {
  date: string;
  loading: boolean;
  t: Translation;
  onRefresh: () => void;
  cooldownSeconds: number;
}

const InlineSpinner: React.FC = () => (
    <svg className="animate-spin h-4 w-4 text-gray-500 dark:text-gray-400" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
        <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
        <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
    </svg>
);

const RefreshIcon: React.FC = () => (
    <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
        <path strokeLinecap="round" strokeLinejoin="round" d="M4 4v5h5M20 20v-5h-5M4 4l1.5 1.5A9 9 0 0120 12h-3a6 6 0 00-9.45-4.55L4 4z" />
    </svg>
);

const CloudOfflineIcon: React.FC = () => (
    <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4 text-gray-400" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
      <path strokeLinecap="round" strokeLinejoin="round" d="M3 15a4 4 0 004 4h9a5 5 0 10-.1-9.999 5.002 5.002 0 10-9.78 2.096A4.001 4.001 0 003 15z" />
    </svg>
);

const formatCooldown = (seconds: number): string => {
    const minutes = Math.floor(seconds / 60);
    const remainingSeconds = seconds % 60;
    return `${minutes}:${remainingSeconds.toString().padStart(2, '0')}`;
}

export const LastUpdated: React.FC<LastUpdatedProps> = ({ date, loading, t, onRefresh, cooldownSeconds }) => {
  const [timeAgo, setTimeAgo] = useState(t.justNow);
  const [isCached, setIsCached] = useState(false);

  useEffect(() => {
    if (loading) return;

    const update = () => {
        const seconds = Math.floor((new Date().getTime() - new Date(date).getTime()) / 1000);

        // Assume data older than 35 mins is effectively "Cached/Offline" since auto-refresh is 30m
        setIsCached(seconds > 35 * 60);

        if (seconds < 5) {
            setTimeAgo(t.justNow);
        } else if (seconds < 60) {
            setTimeAgo(t.secondsAgo(seconds));
        } else {
             setTimeAgo(new Date(date).toLocaleTimeString([], {
                hour: 'numeric',
                minute: '2-digit'
             }));
        }
    };
    update();
    const interval = setInterval(update, 1000);
    return () => clearInterval(interval);
  }, [date, loading, t]);

  const isButtonDisabled = loading || cooldownSeconds > 0;

  const formattedDate = new Date(date).toLocaleDateString('en-US', {
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
  });

  return (
    <div className="mt-4 flex flex-col items-center justify-center gap-1 transition-colors duration-300">
        <div className="flex items-center gap-2 text-sm text-gray-500 dark:text-gray-400">
            {loading ? (
                <>
                <InlineSpinner />
                <span>{t.updatingRates}</span>
                </>
            ) : (
                <>
                <div className="relative flex h-3 w-3">
                    {isCached ? (
                        <span className="relative inline-flex rounded-full h-3 w-3 bg-gray-400"></span>
                    ) : (
                        <>
                        <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-green-400 opacity-75"></span>
                        <span className="relative inline-flex rounded-full h-3 w-3 bg-green-500"></span>
                        </>
                    )}
                </div>
                <span>{t.updated} {timeAgo}</span>
                {isCached && <span className="text-xs bg-gray-100 dark:bg-gray-700 px-1.5 py-0.5 rounded text-gray-500">Cached</span>}
                <button 
                    onClick={onRefresh} 
                    disabled={isButtonDisabled}
                    className="group p-1 rounded-full text-gray-500 dark:text-gray-400 hover:bg-gray-200 dark:hover:bg-gray-700 disabled:opacity-50 disabled:cursor-not-allowed transition-colors focus:outline-none focus:ring-1 focus:ring-sky-500 relative"
                    aria-label="Refresh rates"
                >
                    {cooldownSeconds > 0 ? (
                        <span className="text-xs font-mono w-8">{formatCooldown(cooldownSeconds)}</span>
                    ) : (
                        <RefreshIcon />
                    )}

                    {cooldownSeconds > 0 && (
                        <div className="absolute bottom-full left-1/2 -translate-x-1/2 mb-2 px-2 py-1 bg-gray-800 text-white text-xs font-semibold rounded-md shadow-lg whitespace-nowrap opacity-0 group-hover:opacity-100 transition-opacity pointer-events-none z-10">
                            {t.refreshCooldown(formatCooldown(cooldownSeconds))}
                        </div>
                    )}
                </button>
                </>
            )}
        </div>
        <div className="text-[10px] md:text-xs text-gray-400 dark:text-gray-500 font-mono tracking-wider">
            {formattedDate}
        </div>
    </div>
  );
};

import { useState, useEffect, useCallback, useRef } from 'react';
import type { ExchangeRateData, GroundingChunk, ExchangeRateErrorType, RateHistoryEntry } from '../types';
import { GoogleGenAI } from "@google/genai";

const FETCH_INTERVAL_MS = 30 * 60 * 1000; // 30 minutes
const REFRESH_COOLDOWN_MS = 5 * 60 * 1000; // 5 minutes
const VERY_STALE_THRESHOLD_MS = 12 * 60 * 60 * 1000; // 12 Hours
const MAX_RETRIES = 3;
const RETRY_DELAY_MS = 2000;

const CACHED_RATE_KEY = 'dinarLive_cachedRate';
const CACHED_SOURCES_KEY = 'dinarLive_cachedSources';
const CACHED_HISTORY_KEY = 'dinarLive_cachedHistory';
const LAST_REFRESH_KEY = 'dinarLive_lastRefresh';

const getInitialState = <T,>(key: string): T | null => {
    try {
        const item = localStorage.getItem(key);
        return item ? JSON.parse(item) : null;
    } catch (error) {
        console.warn(`Error reading localStorage key “${key}”:`, error);
        return null;
    }
};

const isCacheValid = () => {
    try {
        const lastRefresh = localStorage.getItem(LAST_REFRESH_KEY);
        if (!lastRefresh) return false;
        const lastRefreshTime = parseInt(lastRefresh, 10);
        return (Date.now() - lastRefreshTime) < VERY_STALE_THRESHOLD_MS;
    } catch { return false; }
};

export const useExchangeRate = () => {
  // Only load cached rate if it's not very stale
  const [rate, setRate] = useState<ExchangeRateData | null>(() => {
      if (!isCacheValid()) return null;
      return getInitialState<ExchangeRateData>(CACHED_RATE_KEY);
  });

  const [sources, setSources] = useState<GroundingChunk[]>(() => {
      // Sources usually correspond to the rate, so clear them if rate is invalid
      if (!isCacheValid()) return [];
      return getInitialState<GroundingChunk[]>(CACHED_SOURCES_KEY) || [];
  });

  // History can persist longer as it is historical data
  const [rateHistory, setRateHistory] = useState<RateHistoryEntry[]>(() => getInitialState<RateHistoryEntry[]>(CACHED_HISTORY_KEY) || []);

  const [isLoading, setIsLoading] = useState<boolean>(!rate);
  const [error, setError] = useState<ExchangeRateErrorType>(null);
  const [cooldownSeconds, setCooldownSeconds] = useState(0);

  const retryCount = useRef(0);
  const cooldownTimerRef = useRef<number | null>(null);

  const updateCooldown = useCallback(() => {
    const lastRefreshTime = getInitialState<number>(LAST_REFRESH_KEY);
    if (!lastRefreshTime) {
      setCooldownSeconds(0);
      return;
    }
    const timeSinceLastRefresh = Date.now() - lastRefreshTime;
    const remainingCooldown = REFRESH_COOLDOWN_MS - timeSinceLastRefresh;

    if (remainingCooldown > 0) {
      setCooldownSeconds(Math.ceil(remainingCooldown / 1000));
    } else {
      setCooldownSeconds(0);
    }
  }, []);

  useEffect(() => {
    updateCooldown();
    cooldownTimerRef.current = window.setInterval(updateCooldown, 1000);
    return () => {
      if (cooldownTimerRef.current) clearInterval(cooldownTimerRef.current);
    };
  }, [updateCooldown]);

  const fetchExchangeRate = useCallback(async () => {
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

      const prompt = `
        **URGENT EXTRACTION TASK**
        You must fetch the latest exchange rates for the Iraqi Dinar (IQD) from these TWO specific sources. Do NOT use cached or generic data.

        **1. MARKET RATES (Telegram):**
        Source: https://t.me/s/iraqborsa
        Message Format: "*100$=145,950 سلێمانی پێنجی*" or "*100$=145,850 هەولێر پێنجی*"
        Action: Find the MOST RECENT message for each city.
        - **Sulaymaniyah (سلێمانی)**: Get value next to "سلێمانی پێنجی".
        - **Erbil (هەولێر)**: Get value next to "هەولێر پێنجی".
        - **Duhok (دهۆک)**: Get value next to "دهۆک پێنجی".

        **2. OFFICIAL RATE (Credit Bank):**
        Source: https://www.creditbankofiraq.com.iq/personal/currency-rates.html
        Action: Find "US Dollar" and its corresponding "Sell Rate".
        Expected result: near 1320 or 132,000.

        **3. OTHER RATES:**
        - Get global USD to EUR, TRY, GBP, and IRT (Toman) rates.
        - Get 7-day Sulaymaniyah price history (USD to IQD).

        **REQUIRED JSON OUTPUT:**
        {
          "current": {
            "suly100Usd": number,
            "erbil100Usd": number,
            "duhok100Usd": number,
            "officialRate": number,
            "eurPerUsd": number,
            "tryPerUsd": number,
            "gbpPerUsd": number,
            "irtPerUsd": number
          },
          "history": [
            { "date": "YYYY-MM-DD", "rate": number }
          ]
        }
      `;

      const response = await ai.models.generateContent({
        model: 'gemini-3-pro-preview',
        contents: prompt,
        config: {
          tools: [{ googleSearch: {} }],
        },
      });

      const rawText = response.text;
      const jsonMatch = rawText.match(/\{[\s\S]*\}/);

      if (!jsonMatch) throw new Error("AI failed to return valid JSON");

      const parsedData = JSON.parse(jsonMatch[0]);

      const suly = parsedData.current?.suly100Usd || 0;
      const erbil = parsedData.current?.erbil100Usd || 0;
      const duhok = parsedData.current?.duhok100Usd || 0;
      const official = parsedData.current?.officialRate || 1320;

      // Validation check - if suly is suspiciously generic or zero, fail and retry
      if (suly < 100000 || suly === 141300) {
        throw new Error("Extracted rate is either static fallback or invalid");
      }

      const normalizedOfficial = official > 10000 ? official / 100 : official;

      const newRate: ExchangeRateData = {
        iqd: suly / 100,
        centralBankRate: normalizedOfficial,
        cities: {
            sulaymaniyah: suly,
            erbil: erbil || suly,
            duhok: duhok || suly,
        },
        eurPerUsd: parsedData.current.eurPerUsd || 0,
        tryPerUsd: parsedData.current.tryPerUsd || 0,
        gbpPerUsd: parsedData.current.gbpPerUsd || 0,
        irtPerUsd: parsedData.current.irtPerUsd || 0,
        updated: new Date().toISOString(),
      };

      let newHistory: RateHistoryEntry[] = [];
      if (Array.isArray(parsedData.history)) {
          newHistory = parsedData.history
            .map((item: any) => ({
                date: item.date,
                rate: item.rate < 5000 ? item.rate * 100 : item.rate
            }))
            .filter((item: any) => item.rate > 100000)
            .sort((a: any, b: any) => new Date(a.date).getTime() - new Date(b.date).getTime())
            .slice(-7);
      }

      const groundingChunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks as GroundingChunk[] ?? [];
      const uniqueChunks = Array.from(new Map(groundingChunks.filter(item => item.web?.uri).map(item => [item.web!.uri, item])).values());

      setRate(newRate);
      setSources(uniqueChunks);
      if (newHistory.length > 0) {
          setRateHistory(newHistory);
          localStorage.setItem(CACHED_HISTORY_KEY, JSON.stringify(newHistory));
      }

      localStorage.setItem(CACHED_RATE_KEY, JSON.stringify(newRate));
      localStorage.setItem(CACHED_SOURCES_KEY, JSON.stringify(uniqueChunks));
      localStorage.setItem(LAST_REFRESH_KEY, JSON.stringify(Date.now())); // Ensure last refresh is updated on success

      retryCount.current = 0;
      setError(null);
      setIsLoading(false);

    } catch (e: unknown) {
      console.error(`Fetch failed:`, (e as Error).message);
      retryCount.current++;
      if (retryCount.current < MAX_RETRIES) {
        setTimeout(fetchExchangeRate, RETRY_DELAY_MS);
      } else {
        setError('FAILED_AFTER_RETRIES');
        setIsLoading(false);
      }
    }
  }, []);

  const startFetchCycle = useCallback(async (isManualRefresh = false) => {
    if (isManualRefresh) {
      const lastRefreshTime = getInitialState<number>(LAST_REFRESH_KEY);
      if (lastRefreshTime && (Date.now() - lastRefreshTime < REFRESH_COOLDOWN_MS)) {
        updateCooldown(); 
        return;
      }
      // Note: We don't set LAST_REFRESH_KEY here, we set it on success in fetchExchangeRate
      // to avoid locking the cooldown if the fetch fails immediately.
      updateCooldown();
    }

    retryCount.current = 0;
    setIsLoading(true);
    setError(null);
    await fetchExchangeRate();
  }, [fetchExchangeRate, updateCooldown]);

  // Initial load and Interval
  useEffect(() => {
    const lastRefreshTime = getInitialState<number>(LAST_REFRESH_KEY);
    const now = Date.now();

    // If no rate, or rate is stale (older than interval), fetch immediately
    if (!rate || (lastRefreshTime && now - lastRefreshTime > FETCH_INTERVAL_MS)) {
        startFetchCycle(false);
    }

    const intervalId = setInterval(() => {
        // Double check stale status before firing interval to prevent double-fetching with focus effect
        const currentLastRefresh = getInitialState<number>(LAST_REFRESH_KEY);
        if (!currentLastRefresh || (Date.now() - currentLastRefresh > FETCH_INTERVAL_MS)) {
             startFetchCycle(false);
        }
    }, FETCH_INTERVAL_MS);

    return () => clearInterval(intervalId);
  }, [startFetchCycle, rate]);

  // Refetch on Window Focus (background running simulation)
  useEffect(() => {
    const handleVisibilityChange = () => {
        if (document.visibilityState === 'visible') {
            const lastRefreshTime = getInitialState<number>(LAST_REFRESH_KEY);
            const now = Date.now();

            // If data is older than 30 minutes when returning to tab, refresh immediately
            if (lastRefreshTime && (now - lastRefreshTime > FETCH_INTERVAL_MS)) {

                // If data is VERY stale (e.g. user absent for > 12 hours), clear rate to force skeleton loading state
                // This ensures users don't see days-old data while fetching
                if (now - lastRefreshTime > VERY_STALE_THRESHOLD_MS) {
                    setRate(null);
                }

                console.log("Tab focused and data stale, refreshing...");
                startFetchCycle(false);
            }
        }
    };

    document.addEventListener('visibilitychange', handleVisibilityChange);
    return () => document.removeEventListener('visibilitychange', handleVisibilityChange);
  }, [startFetchCycle]);

  return {
    rate,
    sources,
    loading: isLoading,
    error,
    refetch: () => startFetchCycle(true),
    rateHistory,
    cooldownSeconds,
  };
};

import React, { useMemo, useState, useEffect, useCallback } from 'react';
import { useExchangeRate } from './hooks/useExchangeRate';
import { Header } from './components/Header';
import { RateDisplay } from './components/RateDisplay';
import { LastUpdated } from './components/LastUpdated';
import { Calculator } from './components/Calculator';
import { translations } from './translations';
import { ThemeToggle } from './components/ThemeToggle';
import { RateDisplaySkeleton } from './components/RateDisplaySkeleton';
import { ComparisonRates } from './components/ComparisonRates';
import { ComparisonRatesSkeleton } from './components/ComparisonRatesSkeleton';
import { useLanguage } from './hooks/useLanguage';
import { LanguageSelector } from './components/LanguageSelector';
import { Dialog } from './components/Dialog';
import { Footer } from './components/Footer';
import { StartupLoader } from './components/StartupLoader';
import { ChatFab } from './components/ChatFab';
import { ChatDialog } from './components/ChatDialog';
import { RateHistoryChart } from './components/RateHistoryChart';
import { RateHistoryChartSkeleton } from './components/RateHistoryChartSkeleton';
import { CurrencyInfoModal } from './components/CurrencyInfoModal';
import { BuyCurrencyModal } from './components/BuyCurrencyModal';

const ChevronIcon: React.FC<{ className?: string }> = ({ className }) => (
  <svg xmlns="http://www.w3.org/2000/svg" className={className} fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
    <path strokeLinecap="round" strokeLinejoin="round" d="M19 9l-7 7-7-7" />
  </svg>
);

const isLargeScreen = () => {
    if (typeof window === 'undefined') return false;
    return window.matchMedia('(min-width: 1024px)').matches;
};

export default function App(): React.ReactElement {
  const { rate, loading, error, refetch, rateHistory, cooldownSeconds } = useExchangeRate();

  const [isCalculatorOpen, setIsCalculatorOpen] = useState(isLargeScreen());
  const [isChartOpen, setIsChartOpen] = useState(isLargeScreen());
  const [language, setLanguage] = useLanguage();
  const [isAboutOpen, setIsAboutOpen] = useState(false);
  const [isChatOpen, setIsChatOpen] = useState(false);
  const [shareFeedback, setShareFeedback] = useState('');
  const [isManualRefreshing, setIsManualRefreshing] = useState(false);
  const [modalState, setModalState] = useState<{ currency: string | null; view: 'info' | 'buy' }>({ currency: null, view: 'info' });
  const t = translations[language];

  const iqdRateValue = useMemo(() => rate?.iqd ?? 0, [rate]);
  const officialRateValue = useMemo(() => rate?.centralBankRate ?? 1310, [rate]);
  const eurPerUsdValue = useMemo(() => rate?.eurPerUsd ?? 0, [rate]);
  const tryPerUsdValue = useMemo(() => rate?.tryPerUsd ?? 0, [rate]);
  const gbpPerUsdValue = useMemo(() => rate?.gbpPerUsd ?? 0, [rate]);
  const irtPerUsdValue = useMemo(() => rate?.irtPerUsd ?? 0, [rate]);
  const rateForDisplay = useMemo(() => iqdRateValue * 100, [iqdRateValue]);
  const centralBankRateForDisplay = useMemo(() => officialRateValue * 100, [officialRateValue]);

  // Calculate trends and high/low from history
  const marketTrend = useMemo(() => {
    if (!rateHistory || rateHistory.length < 2) return undefined;

    // Sort history by date ascending just to be safe
    const sortedHistory = [...rateHistory].sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime());

    const latestHistory = sortedHistory[sortedHistory.length - 1];
    const prevHistory = sortedHistory[sortedHistory.length - 2]; 

    let comparisonRate = latestHistory.rate;
    if (Math.abs(comparisonRate - rateForDisplay) < 1 && sortedHistory.length > 1) {
         comparisonRate = prevHistory.rate;
    }

    const diff = rateForDisplay - comparisonRate;
    const percentage = ((diff / comparisonRate) * 100).toFixed(2);

    return {
        direction: diff > 0 ? 'up' as const : diff < 0 ? 'down' as const : 'neutral' as const,
        percentage: Math.abs(parseFloat(percentage)).toString()
    };
  }, [rateHistory, rateForDisplay]);

  const marketHighLow = useMemo(() => {
      if (!rateHistory || rateHistory.length === 0) return undefined;
      const rates = rateHistory.map(r => r.rate);
      // Include current rate in high/low calculation if available
      if (rateForDisplay > 0) rates.push(rateForDisplay);
      return {
          high: Math.max(...rates),
          low: Math.min(...rates)
      };
  }, [rateHistory, rateForDisplay]);

  const allRates = useMemo(() => ({
    IQD: iqdRateValue,
    USD: 1,
    EUR: eurPerUsdValue,
    TRY: tryPerUsdValue,
    GBP: gbpPerUsdValue,
    IRT: irtPerUsdValue,
  }), [iqdRateValue, eurPerUsdValue, tryPerUsdValue, gbpPerUsdValue, irtPerUsdValue]);

  // Initial loading state: we have NO data to show at all.
  // If we have history but no rate (due to stale expiration), we prefer showing skeletons in the UI over a full screen loader.
  const isCompletelyEmpty = loading && !rate && rateHistory.length === 0 && !error;
  const showFullScreenLoader = isCompletelyEmpty || isManualRefreshing;

  const handleManualRefresh = async () => {
    if (loading || cooldownSeconds > 0) return;
    setIsManualRefreshing(true);
    try {
        await refetch();
    } finally {
        setIsManualRefreshing(false);
    }
  };

  const handleShare = async () => {
    if (!rate) return;
    const shareText = t.shareMessage(Math.floor(rateForDisplay).toLocaleString(), centralBankRateForDisplay.toLocaleString());
    const shareData: ShareData = { title: t.headerTitle, text: shareText };
    const isShareableUrl = window.location.protocol.startsWith('http');
    if (isShareableUrl) shareData.url = window.location.href;

    if (navigator.share) {
      try { await navigator.share(shareData); } catch (err) { if ((err as Error).name !== 'AbortError') console.error('Error sharing:', err); }
    } else {
      try {
        const clipboardText = isShareableUrl ? `${shareText}\n\n${window.location.href}` : shareText;
        await navigator.clipboard.writeText(clipboardText);
        setShareFeedback(t.copiedToClipboard);
        setTimeout(() => setShareFeedback(''), 2000);
      } catch (err) { console.error('Error copying to clipboard:', err); }
    }
  };

  const handleCurrencySelect = (currencyCode: string) => {
    setModalState({ currency: currencyCode, view: 'info' });
  };
  const handleBuyClick = () => setModalState(prev => ({ ...prev, view: 'buy' }));
  const handleCloseModals = () => setModalState({ currency: null, view: 'info' });

  const cityLabels = useMemo(() => ({
    suly: t.sulyName,
    erbil: t.erbilName,
    duhok: t.duhokName,
    regional: t.regionalRatesTitle
  }), [t]);

  return (
    <>
      {showFullScreenLoader && <StartupLoader t={t} />}

      <div className={`min-h-screen w-full transition-filter duration-500 ${showFullScreenLoader ? 'blur-sm' : ''}`}>
        <main className="w-full max-w-7xl mx-auto p-4 sm:p-6 lg:p-8">
          <header className="flex justify-between items-center mb-6 sm:mb-8">
            <div className="flex items-center gap-2">
                <img src="data:image/svg+xml,%3csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 100 100'%3e%3ccircle cx='50' cy='50' r='48' fill='%23FBBF24' stroke='%23B45309' stroke-width='4'/%3e%3ctext x='50' y='60' font-family='Noto Kufi Arabic, sans-serif' font-size='40' font-weight='bold' fill='%23B45309' text-anchor='middle'%3eد.ع%3c/text%3e%3c/svg%3e" alt="DinarLive Logo" className="h-8 w-8 sm:h-10 sm:w-10" />
                <h1 className="text-xl sm:text-2xl font-bold text-gray-800 dark:text-white tracking-tight">{t.appName}</h1>
            </div>
            <div className="flex items-center gap-2 sm:gap-4">
              <ThemeToggle />
              <LanguageSelector currentLang={language} onChangeLang={setLanguage} />
            </div>
          </header>

          {error && (
            <div className="my-6 text-center text-red-500 bg-red-100 dark:bg-red-900/50 p-6 rounded-2xl transition-colors duration-300 animate-fade-in max-w-2xl mx-auto shadow-lg">
                <p className="text-lg font-semibold">{t.errorAfterRetriesTitle}</p>
                <p className="mt-2">{t.errorAfterRetriesMessage}</p>
                <button onClick={() => refetch()} className="mt-6 px-6 py-2.5 rounded-lg bg-sky-600 text-white font-semibold hover:bg-sky-700 active:bg-sky-800 transition-colors focus:outline-none focus:ring-2 focus:ring-sky-500 focus:ring-offset-2 dark:focus:ring-offset-gray-900">
                    {t.retryButton}
                </button>
            </div>
          )}

          {!error && (
            <div className="grid grid-cols-1 lg:grid-cols-5 gap-6 lg:gap-8">
              <div className="lg:col-span-2 space-y-6">
                <div className="bg-white dark:bg-gray-800/50 rounded-2xl shadow-lg p-1 sm:p-1">
                    <Header t={t} />
                    {(loading && !rate) ? (
                        <div className="mt-6 space-y-4 p-4">
                            <RateDisplaySkeleton />
                            <RateDisplaySkeleton />
                        </div>
                    ) : rate && (
                        <div className="mt-2 space-y-4 animate-fade-in p-4">
                            {/* Hero Market Rate Display */}
                            <RateDisplay
                                value={rateForDisplay}
                                loading={loading}
                                label={t.marketRateLabel}
                                description={t.marketRateDescription}
                                currency={t.iqdCurrency}
                                cities={rate.cities}
                                cityLabels={cityLabels}
                                trend={marketTrend}
                                highLow={marketHighLow}
                                isHero={true}
                            />
                            {/* Standard Central Bank Display */}
                            <RateDisplay
                                value={centralBankRateForDisplay}
                                loading={loading}
                                label={t.centralBankRateLabel}
                                description={t.centralBankRateDescription}
                                currency={t.iqdCurrency}
                            />
                        </div>
                    )}
                </div>

                <div className="bg-white dark:bg-gray-800/50 rounded-2xl shadow-lg p-5 sm:p-6">
                    {(loading && !rate) ? (
                        <ComparisonRatesSkeleton />
                    ) : rate && (
                        <ComparisonRates 
                            iqdRate={iqdRateValue}
                            eurRate={eurPerUsdValue}
                            tryRate={tryPerUsdValue}
                            gbpRate={gbpPerUsdValue}
                            irtRate={irtPerUsdValue}
                            t={t}
                            onCurrencySelect={handleCurrencySelect}
                        />
                    )}
                </div>

                {rate && (
                    <div className="bg-white dark:bg-gray-800/50 rounded-2xl shadow-lg p-5 sm:p-6 animate-fade-in">
                        <LastUpdated date={rate.updated} loading={loading} t={t} onRefresh={handleManualRefresh} cooldownSeconds={cooldownSeconds} />
                        <Footer onAboutClick={() => setIsAboutOpen(true)} onShareClick={handleShare} shareFeedback={shareFeedback} t={t} />
                    </div>
                )}
              </div>

              <div className="lg:col-span-3 space-y-6">
                <div className="bg-white dark:bg-gray-800/50 rounded-2xl shadow-lg p-5 sm:p-6">
                    <button onClick={() => setIsChartOpen(prev => !prev)} className="w-full flex items-center justify-between p-2 -m-2 rounded-lg hover:bg-gray-100 dark:hover:bg-gray-700/50 focus:outline-none focus-visible:ring-2 focus-visible:ring-sky-500" aria-expanded={isChartOpen} aria-controls="chart-content">
                        <h2 className="text-lg md:text-xl font-bold text-gray-700 dark:text-gray-200">{t.rateHistoryTitle}</h2>
                        <ChevronIcon className={`w-6 h-6 text-gray-500 dark:text-gray-400 transition-transform duration-300 ${isChartOpen ? 'rotate-180' : ''}`} />
                    </button>
                    <div id="chart-content" className={`transition-all duration-500 ease-in-out overflow-hidden ${isChartOpen ? 'max-h-[500px] opacity-100 mt-4' : 'max-h-0 opacity-0'}`}>
                        {(loading && rateHistory.length === 0) ? <RateHistoryChartSkeleton /> : <RateHistoryChart history={rateHistory} t={t} />}
                    </div>
                </div>

                {rate && (
                    <div className="bg-white dark:bg-gray-800/50 rounded-2xl shadow-lg p-5 sm:p-6 animate-fade-in">
                        <button onClick={() => setIsCalculatorOpen(prev => !prev)} className="w-full flex items-center justify-between p-2 -m-2 rounded-lg hover:bg-gray-100 dark:hover:bg-gray-700/50 focus:outline-none focus-visible:ring-2 focus-visible:ring-sky-500" aria-expanded={isCalculatorOpen} aria-controls="calculator-content">
                            <h2 className="text-lg md:text-xl font-bold text-gray-700 dark:text-gray-200">{t.calculatorTitle}</h2>
                            <ChevronIcon className={`w-6 h-6 text-gray-500 dark:text-gray-400 transition-transform duration-300 ${isCalculatorOpen ? 'rotate-180' : ''}`} />
                        </button>
                        <div id="calculator-content" className={`transition-all duration-500 ease-in-out overflow-hidden ${isCalculatorOpen ? 'max-h-[500px] opacity-100 mt-4' : 'max-h-0 opacity-0'}`}>
                            <Calculator rates={allRates} t={t} onCurrencySelect={handleCurrencySelect} />
                        </div>
                    </div>
                )}
              </div>
            </div>
          )}
        </main>
      </div>

      <Dialog isOpen={isAboutOpen} onClose={() => setIsAboutOpen(false)} title={t.aboutDialogTitle} t={t}>
        <p className="text-sm text-gray-600 dark:text-gray-300 whitespace-pre-line text-center">{t.aboutDialogContent}</p>
      </Dialog>

      {modalState.currency && (
        <>
          <CurrencyInfoModal isOpen={modalState.view === 'info'} onClose={handleCloseModals} onBuy={handleBuyClick} currencyCode={modalState.currency} t={t} />
          <BuyCurrencyModal isOpen={modalState.view === 'buy'} onClose={handleCloseModals} currencyCode={modalState.currency} rates={allRates} t={t} />
        </>
      )}
      {!isCompletelyEmpty && (
        <>
            <ChatFab onClick={() => setIsChatOpen(true)} />
            <ChatDialog isOpen={isChatOpen} onClose={() => setIsChatOpen(false)} rate={rate} t={t} />
        </>
      )}
    </>
  );
}

import React, { useState, useEffect, useRef } from 'react';

interface RateDisplayProps {
  value: number;
  loading: boolean;
  label: string;
  description: string;
  currency: string;
  cities?: {
    sulaymaniyah: number;
    erbil: number;
    duhok: number;
  };
  cityLabels?: {
    suly: string;
    erbil: string;
    duhok: string;
    regional: string;
  };
  trend?: {
    direction: 'up' | 'down' | 'neutral';
    percentage: string;
  };
  highLow?: {
    high: number;
    low: number;
  };
  isHero?: boolean;
}

const DollarIcon = () => (
    <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6 md:h-8 md:w-8" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
        <path strokeLinecap="round" strokeLinejoin="round" d="M12 8c-1.657 0-3 .895-3 2s1.343 2 3 2 3 .895 3 2-1.343 2-3 2m0-8c1.11 0 2.08.402 2.599 1M12 8V7m0 1v.01M12 16v-1m0 1v.01M12 16c-1.11 0-2.08-.402-2.599-1M12 16H9.401M12 8h2.599M12 8V6m0 12v-2m0-10V4m0 16v-2" />
    </svg>
);

const TrendIcon: React.FC<{ direction: 'up' | 'down' | 'neutral' }> = ({ direction }) => {
  if (direction === 'up') {
    return (
      <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" viewBox="0 0 20 20" fill="currentColor">
        <path fillRule="evenodd" d="M5.293 7.707a1 1 0 010-1.414l4-4a1 1 0 011.414 0l4 4a1 1 0 01-1.414 1.414L11 5.414V17a1 1 0 11-2 0V5.414L6.707 7.707a1 1.0 01-1.414 0z" clipRule="evenodd" />
      </svg>
    );
  }
  if (direction === 'down') {
    return (
      <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" viewBox="0 0 20 20" fill="currentColor">
        <path fillRule="evenodd" d="M14.707 12.293a1 1 0 010 1.414l-4 4a1 1 0 01-1.414 0l-4-4a1 1 0 111.414-1.414L9 14.586V3a1 1 0 012 0v11.586l2.293-2.293a1 1 0 011.414 0z" clipRule="evenodd" />
      </svg>
    );
  }
  return <span className="text-xl font-bold leading-none">-</span>;
};

export const RateDisplay: React.FC<RateDisplayProps> = ({ value, loading, label, description, currency, cities, cityLabels, trend, highLow, isHero = false }) => {
  const [iconHighlightClass, setIconHighlightClass] = useState('');
  const [rateChangeClass, setRateChangeClass] = useState('');
  const prevValueRef = useRef(value);

  useEffect(() => {
    if (prevValueRef.current === value || value === 0) {
        prevValueRef.current = value;
        return;
    }

    setIconHighlightClass('bg-green-100 dark:bg-green-900/50 text-green-600 dark:text-green-400 scale-110');
    const iconTimer = setTimeout(() => setIconHighlightClass(''), 500);

    if (value > prevValueRef.current) setRateChangeClass('text-green-600 dark:text-green-400');
    else if (value < prevValueRef.current) setRateChangeClass('text-red-600 dark:text-red-400');

    const rateTimer = setTimeout(() => setRateChangeClass(''), 500);

    prevValueRef.current = value;
    return () => {
      clearTimeout(iconTimer);
      clearTimeout(rateTimer);
    };
  }, [value]);

  const bgColor = isHero 
    ? 'bg-gradient-to-br from-amber-50/40 via-white to-gray-50 dark:from-amber-900/10 dark:via-gray-800 dark:to-gray-900 border border-amber-100 dark:border-amber-900/30 shadow-xl' 
