            {cityLabels.regional}
          </p>
          <div className="grid grid-cols-3 gap-2">
            {[
              { id: 'suly', label: cityLabels.suly, val: cities.sulaymaniyah, isBase: true },
              { id: 'erbil', label: cityLabels.erbil, val: cities.erbil, isBase: false },
