  const [isSwapping, setIsSwapping] = useState(false);

  const currencies = useMemo(() => [
    { code: 'USD', name: t.usd },
    { code: 'IQD', name: t.iqd },
    { code: 'EUR', name: t.eur },
    { code: 'TRY', name: t.try },
    { code: 'GBP', name: t.gbp },
    { code: 'IRT', name: t.irt },
  ], [t]);

  const currencyTooltips: { [key: string]: keyof Translation } = useMemo(() => ({
    USD: 'usdTooltip',
    IQD: 'iqdTooltip',
    EUR: 'eurTooltip',
    TRY: 'tryTooltip',
    GBP: 'gbpTooltip',
    IRT: 'irtTooltip',
  }), []);

  const directRate = useMemo(() => {
    const fromRate = rates[fromCurrency];
    const toRate = rates[toCurrency];
    if (typeof fromRate !== 'number' || typeof toRate !== 'number' || fromRate <= 0) {
      return 0;
    }
    return toRate / fromRate;
  }, [fromCurrency, toCurrency, rates]);

  const calculatedResult = useMemo(() => {
    const numericAmount = parseFloat(amount);
    if (isNaN(numericAmount) || numericAmount <= 0 || directRate <= 0) {
      return '0';
    }
    const result = numericAmount * directRate;
    const formatOptions: Intl.NumberFormatOptions = {};
    if (toCurrency === 'IQD' || toCurrency === 'IRT') {
        formatOptions.maximumFractionDigits = 0;
    } else {
        formatOptions.minimumFractionDigits = 2;
        formatOptions.maximumFractionDigits = 2;
    }
    return result.toLocaleString('en-US', formatOptions);
  }, [amount, toCurrency, directRate]);

  const handleSwap = () => {
    setRotation(prev => prev + 180);
    setIsSwapping(true);
    const tempFrom = fromCurrency;
    setFromCurrency(toCurrency);
    setToCurrency(tempFrom);
    setTimeout(() => setIsSwapping(false), 300);
  };

  const selectorBaseClass = "w-full appearance-none border rounded-xl py-2.5 sm:py-3 px-2 sm:px-4 text-center font-bold text-sm sm:text-base cursor-pointer focus:outline-none focus:ring-2 focus:ring-sky-500 transition-all duration-300 shadow-sm";
  const selectorStateClass = isSwapping 
    ? "bg-sky-50 dark:bg-sky-900/40 border-sky-300 dark:border-sky-600 text-sky-700 dark:text-sky-300 transform scale-105 ring-2 ring-sky-200 dark:ring-sky-800" 
    : "bg-gray-50 dark:bg-gray-800/40 border-transparent hover:border-gray-300 dark:hover:border-gray-500 text-gray-800 dark:text-white";

  return (
    <div className="flex flex-col gap-4 sm:gap-6 w-full max-w-full overflow-hidden bg-gradient-to-br from-white via-white to-gray-50/50 dark:from-gray-900 dark:via-gray-900 dark:to-sky-950/20 p-5 rounded-2xl border border-gray-100 dark:border-gray-800 shadow-sm transition-all duration-300">
      {/* Amount Input Section */}
      <div className="relative">
        <label htmlFor="amount" className="block text-xs sm:text-sm font-semibold text-gray-500 dark:text-gray-400 mb-1.5 uppercase tracking-wider">{t.amount}</label>
        <div className="relative">
           <input
            id="amount"
            type="number"
            inputMode="decimal"
            value={amount}
            onChange={(e) => setAmount(e.target.value)}
            placeholder={t.amountPlaceholder}
            className="w-full p-3 sm:p-4 pl-4 pr-12 text-lg sm:text-2xl font-bold bg-white/60 dark:bg-gray-800/60 backdrop-blur-sm border-2 border-gray-200 dark:border-gray-700 rounded-xl text-gray-900 dark:text-white focus:ring-2 focus:ring-sky-500 focus:border-sky-500 outline-none transition-all placeholder:text-gray-300 dark:placeholder:text-gray-600 shadow-sm"
            dir="ltr"
          />
        </div>
      </div>

      {/* Currency Selection Grid */}
      <div className="relative grid grid-cols-[minmax(0,1fr)_auto_minmax(0,1fr)] items-end gap-2 sm:gap-4">
        {/* FROM Currency */}
        <div className="flex flex-col gap-1.5 min-w-0">
          <label className="text-[10px] sm:text-sm font-semibold text-gray-500 dark:text-gray-400 truncate uppercase tracking-wider">{t.from}</label>
          <Tooltip text={t[currencyTooltips[fromCurrency]]} className="w-full">
            <div className="relative w-full">
              <select 
                value={fromCurrency} 
                onChange={e => setFromCurrency(e.target.value)} 
                className={`${selectorBaseClass} ${selectorStateClass}`}
              >
                {currencies.map(c => (
                  <option key={c.code} value={c.code} className="text-gray-900 dark:text-white bg-white dark:bg-gray-800">
                    {c.code} - {c.name}
                  </option>
                ))}
              </select>
            </div>
          </Tooltip>
        </div>

        {/* Swap Button */}
        <div className="flex flex-col justify-end pb-0.5 flex-shrink-0">
            <button 
                onClick={handleSwap} 
                className="p-2 sm:p-3 bg-sky-100 dark:bg-sky-900/30 text-sky-600 dark:text-sky-400 rounded-full hover:bg-sky-200 dark:hover:bg-sky-800 active:bg-sky-300 dark:active:bg-sky-700 transition-all shadow-md focus:outline-none focus:ring-2 focus:ring-sky-500 z-10"
                aria-label="Swap currencies"
            >
                <SwapIcon 
                  className="w-5 h-5 sm:w-6 sm:h-6 transition-transform duration-500 ease-in-out" 
                  style={{ transform: `rotate(${rotation}deg)` }}
                />
            </button>
        </div>

        {/* TO Currency */}
        <div className="flex flex-col gap-1.5 min-w-0">
          <label className="text-[10px] sm:text-sm font-semibold text-gray-500 dark:text-gray-400 truncate uppercase tracking-wider">{t.to}</label>
          <Tooltip text={t[currencyTooltips[toCurrency]]} className="w-full">
            <div className="relative w-full">
              <select 
                value={toCurrency} 
                onChange={e => setToCurrency(e.target.value)} 
                className={`${selectorBaseClass} ${selectorStateClass}`}
              >
                 {currencies.map(c => (
                  <option key={c.code} value={c.code} className="text-gray-900 dark:text-white bg-white dark:bg-gray-800">
                    {c.code} - {c.name}
                  </option>
                ))}
              </select>
            </div>
          </Tooltip>
        </div>
      </div>

      {/* Result Card */}
      <Tooltip text={t.resultTooltip} className="w-full">
        <div className="bg-gradient-to-br from-green-50 to-emerald-50 dark:from-green-900/10 dark:to-emerald-900/10 border border-green-100 dark:border-green-800/50 rounded-2xl p-5 sm:p-6 text-center shadow-sm w-full overflow-hidden relative">
          <p className="text-[10px] sm:text-sm font-medium text-green-600 dark:text-green-400 mb-2 uppercase tracking-widest">{t.result}</p>
          <p className="text-2xl sm:text-4xl font-extrabold font-mono text-green-800 dark:text-green-100 break-words leading-tight" dir="ltr">
             {calculatedResult}
          </p>

          {directRate > 0 && fromCurrency !== toCurrency && (
              <div className="mt-4 flex flex-col items-center gap-1.5">
                  <div className="inline-block bg-white/50 dark:bg-black/30 px-3 py-1 rounded-full border border-green-100 dark:border-green-800/30 max-w-full">
                      <p className="text-[10px] sm:text-xs text-green-700 dark:text-green-300 font-mono truncate" dir="ltr">
                        1{' '}
                        <button 
                            onClick={() => onCurrencySelect(fromCurrency)}
                            className="font-bold hover:underline cursor-pointer focus:outline-none focus:text-green-800 dark:focus:text-green-200"
                        >
                            {fromCurrency}
                        </button>
                        {' '}≈{' '}
                        {directRate.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 4 })}
                        {' '}
                        <button 
                            onClick={() => onCurrencySelect(toCurrency)}
                            className="font-bold hover:underline cursor-pointer focus:outline-none focus:text-green-800 dark:focus:text-green-200"
                        >
                            {toCurrency}
                        </button>
                      </p>
                  </div>

                  {/* Localized Live Rate Text */}
                  <div className="flex items-center gap-2 text-[10px] text-gray-400 dark:text-gray-500 font-medium">
                      <span className="flex items-center gap-1">
                          <span className="w-1.5 h-1.5 rounded-full bg-green-500 animate-pulse"></span>
                          <span>{t.liveRate}</span>
                      </span>
                      <span>•</span>
                      <span>{new Date().toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'})}</span>
                  </div>
              </div>
          )}
        </div>
      </Tooltip>
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';

interface RateDisplayProps {
  value: number;
  loading: boolean;
  label: string;
  description: string;
  currency: string;
  cities?: {
    sulaymaniyah: number;
    erbil: number;
    duhok: number;
  };
  cityLabels?: {
    suly: string;
    erbil: string;
    duhok: string;
    regional: string;
  };
  trend?: {
    direction: 'up' | 'down' | 'neutral';
    percentage: string;
  };
  highLow?: {
    high: number;
    low: number;
  };
  isHero?: boolean;
}

const DollarIcon = () => (
    <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6 md:h-8 md:w-8" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
        <path strokeLinecap="round" strokeLinejoin="round" d="M12 8c-1.657 0-3 .895-3 2s1.343 2 3 2 3 .895 3 2-1.343 2-3 2m0-8c1.11 0 2.08.402 2.599 1M12 8V7m0 1v.01M12 16v-1m0 1v.01M12 16c-1.11 0-2.08-.402-2.599-1M12 16H9.401M12 8h2.599M12 8V6m0 12v-2m0-10V4m0 16v-2" />
    </svg>
);

const TrendIcon: React.FC<{ direction: 'up' | 'down' | 'neutral' }> = ({ direction }) => {
  if (direction === 'up') {
    return (
      <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" viewBox="0 0 20 20" fill="currentColor">
        <path fillRule="evenodd" d="M5.293 7.707a1 1 0 010-1.414l4-4a1 1 0 011.414 0l4 4a1 1 0 01-1.414 1.414L11 5.414V17a1 1 0 11-2 0V5.414L6.707 7.707a1 1.0 01-1.414 0z" clipRule="evenodd" />
      </svg>
    );
  }
  if (direction === 'down') {
    return (
      <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" viewBox="0 0 20 20" fill="currentColor">
        <path fillRule="evenodd" d="M14.707 12.293a1 1 0 010 1.414l-4 4a1 1 0 01-1.414 0l-4-4a1 1 0 111.414-1.414L9 14.586V3a1 1 0 012 0v11.586l2.293-2.293a1 1 0 011.414 0z" clipRule="evenodd" />
      </svg>
    );
  }
  return <span className="text-xl font-bold leading-none">-</span>;
};

export const RateDisplay: React.FC<RateDisplayProps> = ({ value, loading, label, description, currency, cities, cityLabels, trend, highLow, isHero = false }) => {
  const [iconHighlightClass, setIconHighlightClass] = useState('');
  const [rateChangeClass, setRateChangeClass] = useState('');
  const prevValueRef = useRef(value);

  useEffect(() => {
    if (prevValueRef.current === value || value === 0) {
        prevValueRef.current = value;
        return;
    }

    setIconHighlightClass('bg-green-100 dark:bg-green-900/50 text-green-600 dark:text-green-400 scale-110');
    const iconTimer = setTimeout(() => setIconHighlightClass(''), 500);

    if (value > prevValueRef.current) setRateChangeClass('text-green-600 dark:text-green-400');
    else if (value < prevValueRef.current) setRateChangeClass('text-red-600 dark:text-red-400');

    const rateTimer = setTimeout(() => setRateChangeClass(''), 500);

    prevValueRef.current = value;
    return () => {
      clearTimeout(iconTimer);
      clearTimeout(rateTimer);
    };
  }, [value]);

  const bgColor = isHero 
    ? 'bg-gradient-to-br from-amber-50/40 via-white to-gray-50 dark:from-amber-900/10 dark:via-gray-800 dark:to-gray-900 border border-amber-100 dark:border-amber-900/30 shadow-xl' 
    : 'bg-gradient-to-br from-sky-50/40 via-white to-gray-50 dark:from-sky-900/10 dark:via-gray-800 dark:to-gray-900 border border-sky-100 dark:border-sky-900/30 shadow-lg';

  const iconClasses = iconHighlightClass || (isHero 
    ? 'bg-amber-100 dark:bg-amber-900/40 text-amber-600 dark:text-amber-400' 
    : 'bg-sky-100 dark:bg-sky-900/40 text-sky-600 dark:text-sky-400');

  return (
    <div className={`p-5 md:p-6 rounded-2xl ${bgColor} transition-all duration-300 relative overflow-hidden`}>
      <div className="flex items-start justify-between mb-2">
        <div className="flex items-center space-x-3 rtl:space-x-reverse">
           <div className={`p-3 rounded-2xl border border-white/20 transition-all duration-500 ${iconClasses}`}>
              <DollarIcon />
           </div>
          <div>
            <p className={`font-bold ${isHero ? 'text-lg md:text-xl text-gray-800 dark:text-white' : 'text-base text-gray-700 dark:text-gray-200'}`}>{label}</p>
            <p className="text-xs text-gray-500 dark:text-gray-400">{description}</p>
          </div>
        </div>
        {isHero && trend && (
           <div className={`flex items-center gap-1 px-2.5 py-1 rounded-full text-xs font-bold bg-opacity-10 dark:bg-opacity-20 ${trend.direction === 'up' ? 'bg-green-100 text-green-700 dark:bg-green-900 dark:text-green-300' : trend.direction === 'down' ? 'bg-red-100 text-red-700 dark:bg-red-900 dark:text-red-300' : 'bg-gray-100 text-gray-600'}`}>
              <TrendIcon direction={trend.direction} />
              <span dir="ltr">{trend.percentage}%</span>
           </div>
        )}
      </div>

      <div className="mt-4 flex items-end justify-between">
         <div>
            <p className={`${isHero ? 'text-4xl md:text-5xl' : 'text-2xl md:text-3xl'} font-extrabold tracking-tight relative transition-colors duration-300 ${rateChangeClass || 'text-gray-900 dark:text-white'}`} dir="ltr">
                {Math.floor(value).toLocaleString()}
                {loading && (
                <span className="absolute -top-1 -right-4 h-3 w-3">
                    <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-sky-400 opacity-75"></span>
                    <span className="relative inline-flex rounded-full h-3 w-3 bg-sky-500"></span>
                </span>
                )}
            </p>
            <p className="text-sm font-medium text-gray-400 dark:text-gray-500 mt-1">{currency}</p>
         </div>

         {isHero && highLow && (
             <div className="text-right flex flex-col gap-1">
                 <div className="flex items-center justify-end gap-2 text-xs text-gray-500 dark:text-gray-400">
                    <span>H:</span>
                    <span className="font-mono font-bold text-gray-700 dark:text-gray-300">{highLow.high.toLocaleString()}</span>
                 </div>
                 <div className="flex items-center justify-end gap-2 text-xs text-gray-500 dark:text-gray-400">
                    <span>L:</span>
                    <span className="font-mono font-bold text-gray-700 dark:text-gray-300">{highLow.low.toLocaleString()}</span>
                 </div>
             </div>
         )}
      </div>

      {cities && cityLabels && (
        <div className="mt-6 pt-4 border-t border-gray-100 dark:border-gray-700/50">
          <p className="text-[10px] uppercase font-bold text-gray-400 dark:text-gray-500 tracking-widest mb-3">
            {cityLabels.regional}
          </p>
          <div className="grid grid-cols-3 gap-2">
            {[
              { id: 'suly', label: cityLabels.suly, val: cities.sulaymaniyah, isBase: true },
              { id: 'erbil', label: cityLabels.erbil, val: cities.erbil, isBase: false },
              { id: 'duhok', label: cityLabels.duhok, val: cities.duhok, isBase: false }
            ].map(city => {
                return (
                    <div key={city.id} className={`p-2.5 rounded-xl border transition-all ${city.isBase ? 'bg-amber-50 dark:bg-amber-900/10 border-amber-100 dark:border-amber-800/30' : 'bg-gray-50/50 dark:bg-gray-800/30 border-gray-100 dark:border-gray-700/50 shadow-sm'}`}>
                        <div className="flex items-center justify-between mb-1">
                            <p className={`text-[10px] font-bold truncate ${city.isBase ? 'text-amber-700 dark:text-amber-300' : 'text-gray-500 dark:text-gray-400'}`}>{city.label}</p>
                        </div>
                        <p className={`text-xs sm:text-sm font-mono font-bold ${city.isBase ? 'text-amber-900 dark:text-amber-100' : 'text-gray-700 dark:text-gray-300'}`} dir="ltr">
                            {city.val.toLocaleString()}
                        </p>
                    </div>
                );
            })}
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useMemo, useState, useRef, useCallback } from 'react';
import type { RateHistoryEntry, Translation } from '../types';

interface RateHistoryChartProps {
  history: RateHistoryEntry[];
  t: Translation;
}

const SVG_WIDTH = 380;
const SVG_HEIGHT = 200;
const PADDING = { top: 20, right: 20, bottom: 30, left: 60 };
const Y_AXIS_TICKS = 5;

export const RateHistoryChart: React.FC<RateHistoryChartProps> = ({ history, t }) => {
    const [tooltip, setTooltip] = useState<{ x: number; y: number; date: string; rate: number } | null>(null);
    const svgRef = useRef<SVGSVGElement>(null);

    const processedData = useMemo(() => {
        if (!history || history.length < 2) return null;
        return history
            .map(d => ({ ...d, date: new Date(d.date) }))
            .sort((a, b) => a.date.getTime() - b.date.getTime());
    }, [history]);

    const scales = useMemo(() => {
        if (!processedData) return null;
        const rates = processedData.map(d => d.rate);
        const dates = processedData.map(d => d.date.getTime());
        const minRate = Math.min(...rates);
        const maxRate = Math.max(...rates);
        const ratePadding = (maxRate - minRate) * 0.1 || 100;
        return {
            minRate: minRate - ratePadding,
            maxRate: maxRate + ratePadding,
            minDate: Math.min(...dates),
            maxDate: Math.max(...dates),
            realMin: minRate,
            realMax: maxRate
        };
    }, [processedData]);

    const { pathD, areaPathD, yAxisLabels, xAxisLabels } = useMemo(() => {
        if (!processedData || !scales) return { pathD: '', areaPathD: '', yAxisLabels: [], xAxisLabels: [] };
        const { minRate, maxRate, minDate, maxDate } = scales;
        const chartWidth = SVG_WIDTH - PADDING.left - PADDING.right;
        const chartHeight = SVG_HEIGHT - PADDING.top - PADDING.bottom;
        const getX = (date: Date) => PADDING.left + ((date.getTime() - minDate) / (maxDate - minDate)) * chartWidth;
        const getY = (rate: number) => PADDING.top + chartHeight - ((rate - minRate) / (maxRate - minRate)) * chartHeight;

        let path = '';
        processedData.forEach((d, i) => {
            const command = i === 0 ? 'M' : 'L';
            path += `${command}${getX(d.date)},${getY(d.rate)} `;
        });
        const areaPath = `${path} V${SVG_HEIGHT - PADDING.bottom} H${PADDING.left} Z`;
        const yLabels = [];
        for (let i = 0; i < Y_AXIS_TICKS; i++) {
            const rate = minRate + (i / (Y_AXIS_TICKS - 1)) * (maxRate - minRate);
            yLabels.push({
                y: getY(rate),
                label: Math.round(rate / 100) * 100,
            });
        }
        const xLabels = [];
        if (processedData.length > 0) {
             const first = processedData[0];
             const last = processedData[processedData.length - 1];
             xLabels.push({ x: getX(first.date), label: first.date.toLocaleDateString(undefined, { month: 'short', day: 'numeric' }) });
             xLabels.push({ x: getX(last.date), label: last.date.toLocaleDateString(undefined, { month: 'short', day: 'numeric' }) });
        }
        return { pathD: path, areaPathD: areaPath, yAxisLabels: yLabels, xAxisLabels: xLabels };
    }, [processedData, scales]);

    const handleMouseMove = useCallback((event: React.MouseEvent<SVGSVGElement>) => {
        if (!processedData || !scales || !svgRef.current) return;
        const svgRect = svgRef.current.getBoundingClientRect();
        const mouseXInSvg = ((event.clientX - svgRect.left) / svgRect.width) * SVG_WIDTH;

        const chartWidth = SVG_WIDTH - PADDING.left - PADDING.right;
        const { minDate, maxDate, minRate, maxRate } = scales;
        const getX = (date: Date) => PADDING.left + ((date.getTime() - minDate) / (maxDate - minDate)) * chartWidth;
        const getY = (rate: number) => PADDING.top + (SVG_HEIGHT - PADDING.top - PADDING.bottom) - ((rate - minRate) / (maxRate - minRate)) * (SVG_HEIGHT - PADDING.top - PADDING.bottom);

        let closestPoint = processedData[0];
        let minDistance = Infinity;
        for (const point of processedData) {
            const pointX = getX(point.date);
            const distance = Math.abs(pointX - mouseXInSvg);
            if (distance < minDistance) {
                minDistance = distance;
                closestPoint = point;
            }
        }
        setTooltip({
            x: getX(closestPoint.date),
            y: getY(closestPoint.rate),
            date: closestPoint.date.toLocaleString(undefined, { dateStyle: 'medium', timeStyle: 'short' }),
            rate: closestPoint.rate
        });
    }, [processedData, scales]);

    if (!processedData) {
        return <p className="text-center text-sm text-gray-500 dark:text-gray-400 py-4">{t.noHistoryData}</p>;
    }

    const getTooltipStyles = () => {
        if (!tooltip) return {};
        const xPercent = (tooltip.x / SVG_WIDTH) * 100;
        const yPercent = (tooltip.y / SVG_HEIGHT) * 100;
        const isNearRight = xPercent > 70;
        const isNearLeft = xPercent < 30;
        const isNearTop = yPercent < 30;
        let translateX = '-50%';
        if (isNearRight) translateX = '-90%';
        if (isNearLeft) translateX = '-10%';
        let translateY = '-110%'; 
        if (isNearTop) translateY = '20%';
        return {
            left: `${xPercent}%`,
            top: `${yPercent}%`,
            transform: `translate(${translateX}, ${translateY})`,
            zIndex: 50
        };
    };

    return (
        <div className="relative w-full overflow-hidden bg-gradient-to-br from-white via-white to-sky-50/30 dark:from-gray-900 dark:via-gray-900 dark:to-sky-950/20 p-5 rounded-2xl border border-gray-100 dark:border-gray-800 shadow-sm transition-all duration-300">
             <div className="flex justify-between px-2 mb-2">
                <span className="text-[10px] text-gray-400 font-mono">High: <span className="text-gray-600 dark:text-gray-300 font-bold">{scales?.realMax.toLocaleString()}</span></span>
                <span className="text-[10px] text-gray-400 font-mono">Low: <span className="text-gray-600 dark:text-gray-300 font-bold">{scales?.realMin.toLocaleString()}</span></span>
             </div>
            <svg 
                ref={svgRef} 
                viewBox={`0 0 ${SVG_WIDTH} ${SVG_HEIGHT}`} 
                onMouseMove={handleMouseMove} 
                onMouseLeave={() => setTooltip(null)} 
                className="w-full h-auto block"
                style={{ touchAction: 'none' }}
            >
                <defs>
                    <linearGradient id="areaGradient" x1="0" y1="0" x2="0" y2="1">
                        <stop offset="0%" className="text-sky-400 dark:text-sky-500" stopOpacity={0.4} />
                        <stop offset="100%" className="text-sky-400 dark:text-sky-500" stopOpacity={0} />
                    </linearGradient>
                </defs>

                {/* Grid Lines */}
                {yAxisLabels.map(({ y, label }) => (
                    <g key={label}>
                        <line x1={PADDING.left} y1={y} x2={SVG_WIDTH - PADDING.right} y2={y} className="stroke-gray-100 dark:stroke-gray-800" strokeWidth="1" strokeDasharray="4,4" />
                        <text x={PADDING.left - 8} y={y + 4} textAnchor="end" className="text-[9px] fill-gray-400 dark:fill-gray-500 font-mono">{label.toLocaleString()}</text>
                    </g>
                ))}

                {xAxisLabels.map(({ x, label }) => (
                    <text key={label} x={x} y={SVG_HEIGHT - PADDING.bottom + 15} textAnchor="middle" className="text-[10px] fill-gray-500 dark:fill-gray-400 font-medium">{label}</text>
                ))}

                <path d={areaPathD} fill="url(#areaGradient)" />
                <path d={pathD} fill="none" className="stroke-sky-500 dark:stroke-sky-400" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round" />

                {tooltip && (
                    <g>
                        <line x1={tooltip.x} y1={PADDING.top} x2={tooltip.x} y2={SVG_HEIGHT - PADDING.bottom} className="stroke-gray-300 dark:stroke-gray-600" strokeWidth="1" strokeDasharray="3,3" />
                        <circle cx={tooltip.x} cy={tooltip.y} r="5" className="fill-sky-500 stroke-white dark:stroke-gray-800" strokeWidth="2" />
                    </g>
                )}
            </svg>

            {tooltip && (
                 <div 
                    className="absolute p-2 text-center bg-gray-900/95 backdrop-blur-sm text-white rounded-lg shadow-xl pointer-events-none transition-transform duration-75 ease-out border border-gray-700"
                    style={getTooltipStyles()}
                >
                    <p className="text-xs font-bold font-mono tracking-tighter">{tooltip.rate.toLocaleString()}</p>
                    <p className="text-[9px] opacity-70 whitespace-nowrap">{tooltip.date}</p>
                </div>
            )}
        </div>
    );
};

import React, { useState, useEffect } from 'react';
import type { Translation } from '../types';

interface LastUpdatedProps {
  date: string;
  loading: boolean;
  t: Translation;
  onRefresh: () => void;
  cooldownSeconds: number;
}

export const LastUpdated: React.FC<LastUpdatedProps> = ({ date, loading, t }) => {
  const [timeAgo, setTimeAgo] = useState(t.justNow);
  const [isCached, setIsCached] = useState(false);

  useEffect(() => {
    if (loading) return;

    const update = () => {
        const seconds = Math.floor((new Date().getTime() - new Date(date).getTime()) / 1000);
        setIsCached(seconds > 35 * 60);

        if (seconds < 5) {
            setTimeAgo(t.justNow);
        } else if (seconds < 60) {
            setTimeAgo(t.secondsAgo(seconds));
        } else {
             setTimeAgo(new Date(date).toLocaleTimeString([], {
                hour: 'numeric',
                minute: '2-digit'
             }));
        }
    };
    update();
    const interval = setInterval(update, 1000);
    return () => clearInterval(interval);
  }, [date, loading, t]);

  const formattedDate = new Date(date).toLocaleDateString('en-US', {
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
  });

  return (
    <div className="mt-4 flex flex-col items-center justify-center gap-1 transition-colors duration-300">
        <div className="flex items-center gap-2 text-sm text-gray-500 dark:text-gray-400">
            {loading ? (
                <div className="flex items-center gap-2">
                    <span className="relative flex h-2 w-2">
                        <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-sky-400 opacity-75"></span>
                        <span className="relative inline-flex rounded-full h-2 w-2 bg-sky-500"></span>
                    </span>
                    <span>{t.updatingRates}</span>
                </div>
            ) : (
                <>
                <div className="relative flex h-3 w-3">
                    {isCached ? (
                        <span className="relative inline-flex rounded-full h-3 w-3 bg-gray-400"></span>
                    ) : (
                        <>
                        <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-green-400 opacity-75"></span>
                        <span className="relative inline-flex rounded-full h-3 w-3 bg-green-500"></span>
                        </>
                    )}
                </div>
                <span>{t.updated} {timeAgo}</span>
                {isCached && <span className="text-xs bg-gray-100 dark:bg-gray-700 px-1.5 py-0.5 rounded text-gray-500">Cached</span>}
                </>
            )}
        </div>
        <div className="text-[10px] md:text-xs text-gray-400 dark:text-gray-500 font-mono tracking-wider">
            {formattedDate}
        </div>
    </div>
  );
};

