const ChevronIcon: React.FC<{ className?: string }> = ({ className }) => (
  <svg xmlns="http://www.w3.org/2000/svg" className={className} fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
    <path strokeLinecap="round" strokeLinejoin="round" d="M19 9l-7 7-7-7" />
  </svg>
);

const RefreshIcon: React.FC<{ className?: string }> = ({ className }) => (
    <svg xmlns="http://www.w3.org/2000/svg" className={className} fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
        <path strokeLinecap="round" strokeLinejoin="round" d="M4 4v5h5M20 20v-5h-5M4 4l1.5 1.5A9 9 0 0120 12h-3a6 6 0 00-9.45-4.55L4 4z" />
    </svg>
);

const isLargeScreen = () => {
    if (typeof window === 'undefined') return false;
    return window.matchMedia('(min-width: 1024px)').matches;
};

export default function App(): React.ReactElement {
  const { rate, loading, error, refetch, rateHistory, cooldownSeconds } = useExchangeRate();

  const [isCalculatorOpen, setIsCalculatorOpen] = useState(isLargeScreen());
  const [isChartOpen, setIsChartOpen] = useState(isLargeScreen());
  const [language, setLanguage] = useLanguage();
  const [isAboutOpen, setIsAboutOpen] = useState(false);
  const [isChatOpen, setIsChatOpen] = useState(false);
  const [shareFeedback, setShareFeedback] = useState('');
  const [isManualRefreshing, setIsManualRefreshing] = useState(false);
  const [modalState, setModalState] = useState<{ currency: string | null; view: 'info' | 'buy' }>({ currency: null, view: 'info' });
  const [activeConversionIdx, setActiveConversionIdx] = useState(0);
  const t = translations[language];

  const iqdRateValue = useMemo(() => rate?.iqd ?? 0, [rate]);
  const officialRateValue = useMemo(() => rate?.centralBankRate ?? 1310, [rate]);
  const eurPerUsdValue = useMemo(() => rate?.eurPerUsd ?? 0, [rate]);
  const tryPerUsdValue = useMemo(() => rate?.tryPerUsd ?? 0, [rate]);
  const gbpPerUsdValue = useMemo(() => rate?.gbpPerUsd ?? 0, [rate]);
  const irtPerUsdValue = useMemo(() => rate?.irtPerUsd ?? 0, [rate]);
  const rateForDisplay = useMemo(() => iqdRateValue * 100, [iqdRateValue]);
  const centralBankRateForDisplay = useMemo(() => officialRateValue * 100, [officialRateValue]);

  const conversions = useMemo(() => [
      `${t.usd} ↔ ${t.iqd}`,
      `${t.eur} ↔ ${t.iqd}`,
      `${t.gbp} ↔ ${t.iqd}`,
      `${t.try} ↔ ${t.iqd}`,
      `${t.irt} ↔ ${t.iqd}`,
  ], [t]);

  useEffect(() => {
      const interval = setInterval(() => {
          setActiveConversionIdx(prev => (prev + 1) % conversions.length);
      }, 3000);
      return () => clearInterval(interval);
  }, [conversions]);

  const marketTrend = useMemo(() => {
    if (!rateHistory || rateHistory.length < 2) return undefined;
    const sortedHistory = [...rateHistory].sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime());
    const latestHistory = sortedHistory[sortedHistory.length - 1];
    const prevHistory = sortedHistory[sortedHistory.length - 2]; 
    let comparisonRate = latestHistory.rate;
    if (Math.abs(comparisonRate - rateForDisplay) < 1 && sortedHistory.length > 1) {
         comparisonRate = prevHistory.rate;
    }
    const diff = rateForDisplay - comparisonRate;
    const percentage = ((diff / comparisonRate) * 100).toFixed(2);
    return {
        direction: diff > 0 ? 'up' as const : diff < 0 ? 'down' as const : 'neutral' as const,
        percentage: Math.abs(parseFloat(percentage)).toString()
    };
  }, [rateHistory, rateForDisplay]);

  const marketHighLow = useMemo(() => {
      if (!rateHistory || rateHistory.length === 0) return undefined;
      const rates = rateHistory.map(r => r.rate);
      if (rateForDisplay > 0) rates.push(rateForDisplay);
      return { high: Math.max(...rates), low: Math.min(...rates) };
  }, [rateHistory, rateForDisplay]);

  const allRates = useMemo(() => ({
    IQD: iqdRateValue,
    USD: 1,
    EUR: eurPerUsdValue,
    TRY: tryPerUsdValue,
    GBP: gbpPerUsdValue,
    IRT: irtPerUsdValue,
  }), [iqdRateValue, eurPerUsdValue, tryPerUsdValue, gbpPerUsdValue, irtPerUsdValue]);

  const isCompletelyEmpty = loading && !rate && rateHistory.length === 0 && !error;
  const showFullScreenLoader = isCompletelyEmpty || isManualRefreshing;

  const handleManualRefresh = async () => {
    if (loading || cooldownSeconds > 0) return;
    setIsManualRefreshing(true);
    try {
        await refetch();
    } finally {
        setIsManualRefreshing(false);
    }
  };

  const handleShare = async () => {
    if (!rate) return;
    const shareText = t.shareMessage(Math.floor(rateForDisplay).toLocaleString(), centralBankRateForDisplay.toLocaleString());
    const shareData: ShareData = { title: t.headerTitle, text: shareText };
    const isShareableUrl = window.location.protocol.startsWith('http');
    if (isShareableUrl) shareData.url = window.location.href;

    if (navigator.share) {
      try { await navigator.share(shareData); } catch (err) { if ((err as Error).name !== 'AbortError') console.error('Error sharing:', err); }
    } else {
      try {
        const clipboardText = isShareableUrl ? `${shareText}\n\n${window.location.href}` : shareText;
        await navigator.clipboard.writeText(clipboardText);
        setShareFeedback(t.copiedToClipboard);
        setTimeout(() => setShareFeedback(''), 2000);
      } catch (err) { console.error('Error copying to clipboard:', err); }
    }
  };

  const handleCurrencySelect = (currencyCode: string) => {
    setModalState({ currency: currencyCode, view: 'info' });
  };
  const handleBuyClick = () => setModalState(prev => ({ ...prev, view: 'buy' }));
  const handleCloseModals = () => setModalState({ currency: null, view: 'info' });

  const cityLabels = useMemo(() => ({
    suly: t.sulyName,
    erbil: t.erbilName,
    duhok: t.duhokName,
    regional: t.regionalRatesTitle
  }), [t]);

  return (
    <>
      {showFullScreenLoader && <StartupLoader t={t} />}

      <div className={`min-h-screen w-full transition-filter duration-500 ${showFullScreenLoader ? 'blur-sm' : ''}`}>
        <main className="w-full max-w-7xl mx-auto p-4 sm:p-6 lg:p-8">

          <header className="mb-8 flex flex-col gap-6">
            <div className="flex justify-between items-start">
              <div className="flex items-center gap-2">
                  <img src="data:image/svg+xml,%3csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 100 100'%3e%3ccircle cx='50' cy='50' r='48' fill='%23FBBF24' stroke='%23B45309' stroke-width='4'/%3e%3ctext x='50' y='60' font-family='Noto Kufi Arabic, sans-serif' font-size='40' font-weight='bold' fill='%23B45309' text-anchor='middle'%3eد.ع%3c/text%3e%3c/svg%3e" alt="DinarLive Logo" className="h-8 w-8 sm:h-12 sm:w-12" />
                  <div>
                    <h1 className="text-xl sm:text-3xl font-bold text-gray-800 dark:text-white tracking-tight">{t.appName}</h1>
                    <div className="relative h-5 overflow-hidden">
                        <p key={activeConversionIdx} className="text-xs sm:text-sm text-sky-600 dark:text-sky-400 font-semibold animate-slide-fade">
                            {conversions[activeConversionIdx]}
                        </p>
                    </div>
                  </div>
              </div>
              <div className="flex items-center gap-1 sm:gap-3 bg-white/60 dark:bg-gray-800/60 p-1.5 rounded-full shadow-lg border border-gray-200/50 dark:border-gray-700/50 backdrop-blur-md">
                <ThemeToggle />
                <LanguageSelector currentLang={language} onChangeLang={setLanguage} />
                <div className="w-[1px] h-6 bg-gray-200 dark:bg-gray-700 mx-1"></div>
                <button 
                  onClick={handleManualRefresh} 
                  disabled={loading || cooldownSeconds > 0}
                  className="p-2 rounded-full text-gray-500 hover:text-sky-600 hover:bg-sky-50 dark:hover:bg-sky-900/30 transition-all disabled:opacity-30 disabled:cursor-not-allowed group relative"
                  aria-label="Refresh rates"
                >
                  <RefreshIcon className={`w-5 h-5 ${loading ? 'animate-spin text-sky-500' : ''}`} />
                  {cooldownSeconds > 0 && !loading && (
                      <span className="absolute -bottom-1 -right-1 bg-sky-100 dark:bg-sky-900 text-sky-700 dark:text-sky-300 text-[8px] font-bold px-1 rounded-full border border-sky-200 dark:border-sky-800">{cooldownSeconds}</span>
                  )}
                </button>
              </div>
            </div>

            <div className="flex items-center justify-center">
                 {loading && !isCompletelyEmpty && (
                     <div className="flex items-center gap-2 px-5 py-2 bg-gradient-to-r from-sky-50 to-blue-50 dark:from-sky-900/30 dark:to-blue-900/30 rounded-full border border-sky-100 dark:border-sky-800 shadow-sm animate-pulse">
                        <span className="relative flex h-2.5 w-2.5">
                            <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-sky-400 opacity-75"></span>
                            <span className="relative inline-flex rounded-full h-2.5 w-2.5 bg-sky-500"></span>
                        </span>
                        <span className="text-xs font-bold text-sky-700 dark:text-sky-300 uppercase tracking-widest">{t.updatingRates}</span>
                     </div>
                 )}
            </div>
          </header>

          {error && (
            <div className="my-6 text-center text-red-500 bg-red-100 dark:bg-red-900/50 p-6 rounded-2xl transition-colors duration-300 animate-fade-in max-w-2xl mx-auto shadow-lg">
                <p className="text-lg font-semibold">{t.errorAfterRetriesTitle}</p>
                <p className="mt-2">{t.errorAfterRetriesMessage}</p>
                <button onClick={() => refetch()} className="mt-6 px-6 py-2.5 rounded-lg bg-sky-600 text-white font-semibold hover:bg-sky-700 active:bg-sky-800 transition-colors focus:outline-none focus:ring-2 focus:ring-sky-500 focus:ring-offset-2 dark:focus:ring-offset-gray-900">
                    {t.retryButton}
                </button>
            </div>
          )}

          {!error && (
            <div className="grid grid-cols-1 lg:grid-cols-5 gap-6 lg:gap-8">
              <div className="lg:col-span-2 space-y-6">
                <div className="space-y-6">
                    {(loading && !rate) ? (
                        <div className="space-y-4">
                            <RateDisplaySkeleton />
                            <RateDisplaySkeleton />
                        </div>
                    ) : rate && (
                        <div className="space-y-6 animate-fade-in">
                            <RateDisplay
                                value={rateForDisplay}
                                loading={loading}
                                label={t.marketRateLabel}
                                description={t.marketRateDescription}
                                currency={t.iqdCurrency}
                                cities={rate.cities}
                                cityLabels={cityLabels}
                                trend={marketTrend}
                                highLow={marketHighLow}
                                isHero={true}
                            />
                            <RateDisplay
                                value={centralBankRateForDisplay}
                                loading={loading}
                                label={t.centralBankRateLabel}
                                description={t.centralBankRateDescription}
                                currency={t.iqdCurrency}
                            />
                        </div>
                    )}
                </div>

                <div>
                    {(loading && !rate) ? (
                        <ComparisonRatesSkeleton />
                    ) : rate && (
                        <ComparisonRates 
                            iqdRate={iqdRateValue}
                            eurRate={eurPerUsdValue}
                            tryRate={tryPerUsdValue}
                            gbpRate={gbpPerUsdValue}
                            irtRate={irtPerUsdValue}
                            t={t}
                            onCurrencySelect={handleCurrencySelect}
                        />
                    )}
                </div>

                {rate && (
                    <div className="bg-gradient-to-br from-white via-white to-gray-50/50 dark:from-gray-800 dark:via-gray-800 dark:to-gray-900/50 rounded-2xl shadow-lg p-5 sm:p-6 animate-fade-in border border-gray-100 dark:border-gray-700">
                        <LastUpdated date={rate.updated} loading={loading} t={t} onRefresh={handleManualRefresh} cooldownSeconds={cooldownSeconds} />
                        <Footer onAboutClick={() => setIsAboutOpen(true)} onShareClick={handleShare} shareFeedback={shareFeedback} t={t} />
                    </div>
                )}
              </div>

              <div className="lg:col-span-3 space-y-6">
                <div className="space-y-6">
                    <div className="flex items-center justify-between px-2">
                        <h2 className="text-lg md:text-xl font-bold text-gray-700 dark:text-gray-200">{t.rateHistoryTitle}</h2>
                        <button onClick={() => setIsChartOpen(prev => !prev)} className="p-2 rounded-lg hover:bg-gray-100 dark:hover:bg-gray-700 transition-colors">
                            <ChevronIcon className={`w-6 h-6 text-gray-500 dark:text-gray-400 transition-transform duration-300 ${isChartOpen ? 'rotate-180' : ''}`} />
                        </button>
                    </div>
                    <div className={`transition-all duration-500 ease-in-out overflow-hidden ${isChartOpen ? 'max-h-[500px] opacity-100' : 'max-h-0 opacity-0'}`}>
                        {(loading && rateHistory.length === 0) ? <RateHistoryChartSkeleton /> : <RateHistoryChart history={rateHistory} t={t} />}
                    </div>
                </div>

                {rate && (
                    <div className="space-y-6 animate-fade-in">
                        <div className="flex items-center justify-between px-2">
                            <h2 className="text-lg md:text-xl font-bold text-gray-700 dark:text-gray-200">{t.calculatorTitle}</h2>
                            <button onClick={() => setIsCalculatorOpen(prev => !prev)} className="p-2 rounded-lg hover:bg-gray-100 dark:hover:bg-gray-700 transition-colors">
                                <ChevronIcon className={`w-6 h-6 text-gray-500 dark:text-gray-400 transition-transform duration-300 ${isCalculatorOpen ? 'rotate-180' : ''}`} />
                            </button>
                        </div>
                        <div className={`transition-all duration-500 ease-in-out overflow-hidden ${isCalculatorOpen ? 'max-h-[600px] opacity-100' : 'max-h-0 opacity-0'}`}>
                            <Calculator rates={allRates} t={t} onCurrencySelect={handleCurrencySelect} />
                        </div>
                    </div>
                )}
              </div>
            </div>
          )}
        </main>
      </div>

      <Dialog isOpen={isAboutOpen} onClose={() => setIsAboutOpen(false)} title={t.aboutDialogTitle} t={t}>
        <p className="text-sm text-gray-600 dark:text-gray-300 whitespace-pre-line text-center leading-relaxed">{t.aboutDialogContent}</p>
      </Dialog>

      {modalState.currency && (
        <>
          <CurrencyInfoModal isOpen={modalState.view === 'info'} onClose={handleCloseModals} onBuy={handleBuyClick} currencyCode={modalState.currency} t={t} />
          <BuyCurrencyModal isOpen={modalState.view === 'buy'} onClose={handleCloseModals} currencyCode={modalState.currency} rates={allRates} t={t} />
        </>
      )}
      {!isCompletelyEmpty && (
        <>
            <ChatFab onClick={() => setIsChatOpen(true)} />
            <ChatDialog isOpen={isChatOpen} onClose={() => setIsChatOpen(false)} rate={rate} t={t} />
        </>
      )}

      <style>{`
        @keyframes slideFade {
          0% { transform: translateY(100%); opacity: 0; }
          15% { transform: translateY(0); opacity: 1; }
          85% { transform: translateY(0); opacity: 1; }
          100% { transform: translateY(-100%); opacity: 0; }
        }
        .animate-slide-fade { animation: slideFade 3s cubic-bezier(0.4, 0, 0.2, 1) infinite; }
        @keyframes fadeIn { from { opacity: 0; } to { opacity: 1; } }
        .animate-fade-in { animation: fadeIn 0.5s ease-out forwards; }
      `}</style>
    </>
  );
}

import { useState, useEffect, useCallback, useRef } from 'react';
import type { ExchangeRateData, GroundingChunk, ExchangeRateErrorType, RateHistoryEntry } from '../types';
import { GoogleGenAI } from "@google/genai";

const FETCH_INTERVAL_MS = 30 * 60 * 1000; // 30 minutes
const REFRESH_COOLDOWN_MS = 5 * 60 * 1000; // 5 minutes
const VERY_STALE_THRESHOLD_MS = 12 * 60 * 60 * 1000; // 12 Hours
const MAX_RETRIES = 3;
const RETRY_DELAY_MS = 3000;

const CACHED_RATE_KEY = 'dinarLive_cachedRate';
const CACHED_SOURCES_KEY = 'dinarLive_cachedSources';
const CACHED_HISTORY_KEY = 'dinarLive_cachedHistory';
const LAST_REFRESH_KEY = 'dinarLive_lastRefresh';

const getInitialState = <T,>(key: string): T | null => {
    try {
        const item = localStorage.getItem(key);
        return item ? JSON.parse(item) : null;
    } catch (error) {
        console.warn(`Error reading localStorage key “${key}”:`, error);
        return null;
    }
};

const isCacheValid = () => {
    try {
        const lastRefresh = localStorage.getItem(LAST_REFRESH_KEY);
        if (!lastRefresh) return false;
        const lastRefreshTime = parseInt(lastRefresh, 10);
        return (Date.now() - lastRefreshTime) < VERY_STALE_THRESHOLD_MS;
    } catch { return false; }
};

export const useExchangeRate = () => {
  const [rate, setRate] = useState<ExchangeRateData | null>(() => {
      if (!isCacheValid()) return null;
      return getInitialState<ExchangeRateData>(CACHED_RATE_KEY);
  });

  const [sources, setSources] = useState<GroundingChunk[]>(() => {
      if (!isCacheValid()) return [];
      return getInitialState<GroundingChunk[]>(CACHED_SOURCES_KEY) || [];
  });

  const [rateHistory, setRateHistory] = useState<RateHistoryEntry[]>(() => getInitialState<RateHistoryEntry[]>(CACHED_HISTORY_KEY) || []);

  const [isLoading, setIsLoading] = useState<boolean>(!rate);
  const [error, setError] = useState<ExchangeRateErrorType>(null);
  const [cooldownSeconds, setCooldownSeconds] = useState(0);

  const retryCount = useRef(0);
  const cooldownTimerRef = useRef<number | null>(null);

  const updateCooldown = useCallback(() => {
    const lastRefreshTime = getInitialState<number>(LAST_REFRESH_KEY);
    if (!lastRefreshTime) {
      setCooldownSeconds(0);
      return;
    }
    const timeSinceLastRefresh = Date.now() - lastRefreshTime;
    const remainingCooldown = REFRESH_COOLDOWN_MS - timeSinceLastRefresh;

    if (remainingCooldown > 0) {
      setCooldownSeconds(Math.ceil(remainingCooldown / 1000));
    } else {
      setCooldownSeconds(0);
    }
  }, []);

  useEffect(() => {
    updateCooldown();
    cooldownTimerRef.current = window.setInterval(updateCooldown, 1000);
    return () => {
      if (cooldownTimerRef.current) clearInterval(cooldownTimerRef.current);
    };
  }, [updateCooldown]);

  const fetchExchangeRate = useCallback(async () => {
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

      const prompt = `
        **URGENT FINANCIAL DATA EXTRACTION**
        I need the most current exchange rates for the Iraqi Dinar (IQD) vs USD. 
        Date/Time: ${new Date().toLocaleString()}

        **SOURCES:**
        1. Telegram t.me/s/iraqborsa - Extract latest prices for Sulaymaniyah (سلێمانی), Erbil (هەولێر), Duhok (دهۆک).
        2. Central Bank of Iraq (CBI) Official Rate.
        3. Global rates: EUR/USD, TRY/USD, GBP/USD, IRT(Toman)/USD.

        **DATA REQUIREMENTS:**
        - Market Rate (100 USD): usually 145,000 - 155,000 IQD.
        - Official Rate: usually 1310 - 1320 IQD per 1 USD.
        - Historical: 7-day Sulaymaniyah history.

        **OUTPUT VALID JSON ONLY:**
        {
          "current": {
            "suly100Usd": number,
            "erbil100Usd": number,
            "duhok100Usd": number,
            "officialRate": number,
            "eurPerUsd": number,
            "tryPerUsd": number,
            "gbpPerUsd": number,
            "irtPerUsd": number
          },
          "history": [
            { "date": "YYYY-MM-DD", "rate": number }
          ]
        }
      `;

      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: prompt,
        config: {
          tools: [{ googleSearch: {} }],
        },
      });

      const rawText = response.text;
      const jsonMatch = rawText.match(/\{[\s\S]*\}/);

      if (!jsonMatch) throw new Error("AI failed to return valid JSON");

      const parsedData = JSON.parse(jsonMatch[0]);

      const suly = parsedData.current?.suly100Usd || 0;
      const erbil = parsedData.current?.erbil100Usd || 0;
      const duhok = parsedData.current?.duhok100Usd || 0;
      const official = parsedData.current?.officialRate || 1320;

      if (suly < 100000 || suly === 141300) {
        throw new Error("Extracted rate is either static fallback or invalid");
      }

      const normalizedOfficial = official > 10000 ? official / 100 : official;

      const newRate: ExchangeRateData = {
        iqd: suly / 100,
        centralBankRate: normalizedOfficial,
        cities: {
            sulaymaniyah: suly,
            erbil: erbil || suly,
            duhok: duhok || suly,
        },
        eurPerUsd: parsedData.current.eurPerUsd || 0,
        tryPerUsd: parsedData.current.tryPerUsd || 0,
        gbpPerUsd: parsedData.current.gbpPerUsd || 0,
        irtPerUsd: parsedData.current.irtPerUsd || 0,
        updated: new Date().toISOString(),
      };

      let newHistory: RateHistoryEntry[] = [];
      if (Array.isArray(parsedData.history)) {
          newHistory = parsedData.history
            .map((item: any) => ({
                date: item.date,
                rate: item.rate < 5000 ? item.rate * 100 : item.rate
            }))
            .filter((item: any) => item.rate > 100000)
            .sort((a: any, b: any) => new Date(a.date).getTime() - new Date(b.date).getTime())
            .slice(-7);
      }

      const groundingChunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks as GroundingChunk[] ?? [];
      const uniqueChunks = Array.from(new Map(groundingChunks.filter(item => item.web?.uri).map(item => [item.web!.uri, item])).values());

      setRate(newRate);
      setSources(uniqueChunks);
      if (newHistory.length > 0) {
          setRateHistory(newHistory);
          localStorage.setItem(CACHED_HISTORY_KEY, JSON.stringify(newHistory));
      }

      localStorage.setItem(CACHED_RATE_KEY, JSON.stringify(newRate));
      localStorage.setItem(CACHED_SOURCES_KEY, JSON.stringify(uniqueChunks));
      localStorage.setItem(LAST_REFRESH_KEY, JSON.stringify(Date.now()));

      retryCount.current = 0;
      setError(null);
      setIsLoading(false);

    } catch (e: unknown) {
      console.error(`Fetch attempt ${retryCount.current + 1} failed:`, (e as Error).message);
      retryCount.current++;
      if (retryCount.current < MAX_RETRIES) {
        setTimeout(fetchExchangeRate, RETRY_DELAY_MS);
      } else {
        setError('FAILED_AFTER_RETRIES');
        setIsLoading(false);
      }
    }
  }, []);

  const startFetchCycle = useCallback(async (isManualRefresh = false) => {
    if (isManualRefresh) {
      const lastRefreshTime = getInitialState<number>(LAST_REFRESH_KEY);
      if (lastRefreshTime && (Date.now() - lastRefreshTime < REFRESH_COOLDOWN_MS)) {
        updateCooldown(); 
        return;
      }
      updateCooldown();
    }

    retryCount.current = 0;
    setIsLoading(true);
    setError(null);
    await fetchExchangeRate();
  }, [fetchExchangeRate, updateCooldown]);

  useEffect(() => {
    const lastRefreshTime = getInitialState<number>(LAST_REFRESH_KEY);
    const now = Date.now();

    if (!rate || (lastRefreshTime && now - lastRefreshTime > FETCH_INTERVAL_MS)) {
        startFetchCycle(false);
    }

    const intervalId = setInterval(() => {
        const currentLastRefresh = getInitialState<number>(LAST_REFRESH_KEY);
        if (!currentLastRefresh || (Date.now() - currentLastRefresh > FETCH_INTERVAL_MS)) {
             startFetchCycle(false);
        }
    }, FETCH_INTERVAL_MS);

    return () => clearInterval(intervalId);
  }, [startFetchCycle, rate]);

  useEffect(() => {
    const handleVisibilityChange = () => {
        if (document.visibilityState === 'visible') {
            const lastRefreshTime = getInitialState<number>(LAST_REFRESH_KEY);
            const now = Date.now();

            if (lastRefreshTime && (now - lastRefreshTime > FETCH_INTERVAL_MS)) {
                if (now - lastRefreshTime > VERY_STALE_THRESHOLD_MS) {
                    setRate(null);
                }
                startFetchCycle(false);
            }
        }
    };

    document.addEventListener('visibilitychange', handleVisibilityChange);
    return () => document.removeEventListener('visibilitychange', handleVisibilityChange);
  }, [startFetchCycle]);

  return {
    rate,
    sources,
    loading: isLoading,
    error,
    refetch: () => startFetchCycle(true),
    rateHistory,
    cooldownSeconds,
  };
};

import React, { useMemo, useState, useEffect, useCallback } from 'react';
import { useExchangeRate } from './hooks/useExchangeRate';
import { Header } from './components/Header';
import { RateDisplay } from './components/RateDisplay';
import { LastUpdated } from './components/LastUpdated';
import { Calculator } from './components/Calculator';
import { translations } from './translations';
import { ThemeToggle } from './components/ThemeToggle';
import { RateDisplaySkeleton } from './components/RateDisplaySkeleton';
import { ComparisonRates } from './components/ComparisonRates';
import { ComparisonRatesSkeleton } from './components/ComparisonRatesSkeleton';
import { useLanguage } from './hooks/useLanguage';
import { LanguageSelector } from './components/LanguageSelector';
import { Dialog } from './components/Dialog';
import { Footer } from './components/Footer';
import { StartupLoader } from './components/StartupLoader';
import { ChatFab } from './components/ChatFab';
import { ChatDialog } from './components/ChatDialog';
import { RateHistoryChart } from './components/RateHistoryChart';
import { RateHistoryChartSkeleton } from './components/RateHistoryChartSkeleton';
import { CurrencyInfoModal } from './components/CurrencyInfoModal';
import { BuyCurrencyModal } from './components/BuyCurrencyModal';

const ChevronIcon: React.FC<{ className?: string }> = ({ className }) => (
  <svg xmlns="http://www.w3.org/2000/svg" className={className} fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
    <path strokeLinecap="round" strokeLinejoin="round" d="M19 9l-7 7-7-7" />
  </svg>
);

const RefreshIcon: React.FC<{ className?: string }> = ({ className }) => (
    <svg xmlns="http://www.w3.org/2000/svg" className={className} fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
        <path strokeLinecap="round" strokeLinejoin="round" d="M4 4v5h5M20 20v-5h-5M4 4l1.5 1.5A9 9 0 0120 12h-3a6 6 0 00-9.45-4.55L4 4z" />
    </svg>
);

const isLargeScreen = () => {
    if (typeof window === 'undefined') return false;
    return window.matchMedia('(min-width: 1024px)').matches;
};

export default function App(): React.ReactElement {
  const { rate, loading, error, refetch, rateHistory, cooldownSeconds } = useExchangeRate();

  const [isCalculatorOpen, setIsCalculatorOpen] = useState(isLargeScreen());
  const [isChartOpen, setIsChartOpen] = useState(isLargeScreen());
  const [language, setLanguage] = useLanguage();
  const [isAboutOpen, setIsAboutOpen] = useState(false);
  const [isChatOpen, setIsChatOpen] = useState(false);
  const [shareFeedback, setShareFeedback] = useState('');
  const [isManualRefreshing, setIsManualRefreshing] = useState(false);
  const [cooldownMessage, setCooldownMessage] = useState<string | null>(null);
  const [modalState, setModalState] = useState<{ currency: string | null; view: 'info' | 'buy' }>({ currency: null, view: 'info' });
  const [activeConversionIdx, setActiveConversionIdx] = useState(0);
  const t = translations[language];

  const iqdRateValue = useMemo(() => rate?.iqd ?? 0, [rate]);
  const officialRateValue = useMemo(() => rate?.centralBankRate ?? 1310, [rate]);
  const eurPerUsdValue = useMemo(() => rate?.eurPerUsd ?? 0, [rate]);
  const tryPerUsdValue = useMemo(() => rate?.tryPerUsd ?? 0, [rate]);
  const gbpPerUsdValue = useMemo(() => rate?.gbpPerUsd ?? 0, [rate]);
  const irtPerUsdValue = useMemo(() => rate?.irtPerUsd ?? 0, [rate]);
  const rateForDisplay = useMemo(() => iqdRateValue * 100, [iqdRateValue]);
  const centralBankRateForDisplay = useMemo(() => officialRateValue * 100, [officialRateValue]);

  const conversions = useMemo(() => [
      `${t.usd} ↔ ${t.iqd}`,
      `${t.eur} ↔ ${t.iqd}`,
      `${t.gbp} ↔ ${t.iqd}`,
      `${t.try} ↔ ${t.iqd}`,
      `${t.irt} ↔ ${t.iqd}`,
  ], [t]);

  useEffect(() => {
      const interval = setInterval(() => {
          setActiveConversionIdx(prev => (prev + 1) % conversions.length);
      }, 3000);
      return () => clearInterval(interval);
  }, [conversions]);

  const marketTrend = useMemo(() => {
    if (!rateHistory || rateHistory.length < 2) return undefined;
    const sortedHistory = [...rateHistory].sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime());
    const latestHistory = sortedHistory[sortedHistory.length - 1];
    const prevHistory = sortedHistory[sortedHistory.length - 2]; 
    let comparisonRate = latestHistory.rate;
    if (Math.abs(comparisonRate - rateForDisplay) < 1 && sortedHistory.length > 1) {
         comparisonRate = prevHistory.rate;
    }
    const diff = rateForDisplay - comparisonRate;
    const percentage = ((diff / comparisonRate) * 100).toFixed(2);
    return {
        direction: diff > 0 ? 'up' as const : diff < 0 ? 'down' as const : 'neutral' as const,
        percentage: Math.abs(parseFloat(percentage)).toString()
    };
  }, [rateHistory, rateForDisplay]);

  const marketHighLow = useMemo(() => {
      if (!rateHistory || rateHistory.length === 0) return undefined;
      const rates = rateHistory.map(r => r.rate);
      if (rateForDisplay > 0) rates.push(rateForDisplay);
      return { high: Math.max(...rates), low: Math.min(...rates) };
  }, [rateHistory, rateForDisplay]);

  const allRates = useMemo(() => ({
    IQD: iqdRateValue,
    USD: 1,
    EUR: eurPerUsdValue,
    TRY: tryPerUsdValue,
    GBP: gbpPerUsdValue,
    IRT: irtPerUsdValue,
  }), [iqdRateValue, eurPerUsdValue, tryPerUsdValue, gbpPerUsdValue, irtPerUsdValue]);

  const isCompletelyEmpty = loading && !rate && rateHistory.length === 0 && !error;
  const showFullScreenLoader = isCompletelyEmpty || isManualRefreshing;

  const handleManualRefresh = async () => {
    if (loading) return;
    if (cooldownSeconds > 0) {
        setCooldownMessage(t.refreshCooldown(`${cooldownSeconds}s`));
        setTimeout(() => setCooldownMessage(null), 2500);
        return;
    }
    setIsManualRefreshing(true);
    try {
        await refetch();
    } finally {
        setIsManualRefreshing(false);
    }
  };

  const handleShare = async () => {
    if (!rate) return;
    const shareText = t.shareMessage(Math.floor(rateForDisplay).toLocaleString(), centralBankRateForDisplay.toLocaleString());
    const shareData: ShareData = { title: t.headerTitle, text: shareText };
    const isShareableUrl = window.location.protocol.startsWith('http');
    if (isShareableUrl) shareData.url = window.location.href;

    if (navigator.share) {
      try { await navigator.share(shareData); } catch (err) { if ((err as Error).name !== 'AbortError') console.error('Error sharing:', err); }
    } else {
      try {
        const clipboardText = isShareableUrl ? `${shareText}\n\n${window.location.href}` : shareText;
        await navigator.clipboard.writeText(clipboardText);
        setShareFeedback(t.copiedToClipboard);
        setTimeout(() => setShareFeedback(''), 2000);
      } catch (err) { console.error('Error copying to clipboard:', err); }
    }
  };

  const handleCurrencySelect = (currencyCode: string) => {
    setModalState({ currency: currencyCode, view: 'info' });
  };
  const handleBuyClick = () => setModalState(prev => ({ ...prev, view: 'buy' }));
  const handleCloseModals = () => setModalState({ currency: null, view: 'info' });

  const cityLabels = useMemo(() => ({
    suly: t.sulyName,
    erbil: t.erbilName,
    duhok: t.duhokName,
    regional: t.regionalRatesTitle
  }), [t]);

  return (
    <>
      {showFullScreenLoader && <StartupLoader t={t} />}

      <div className={`min-h-screen w-full transition-filter duration-500 ${showFullScreenLoader ? 'blur-sm' : ''}`}>
        <main className="w-full max-w-7xl mx-auto p-4 sm:p-6 lg:p-8">

          <header className="mb-8 flex flex-col gap-6">
            <div className="flex justify-between items-start">
              <div className="flex items-center gap-3">
                  <img src="data:image/svg+xml,%3csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 100 100'%3e%3ccircle cx='50' cy='50' r='48' fill='%23FBBF24' stroke='%23B45309' stroke-width='4'/%3e%3ctext x='50' y='60' font-family='Noto Kufi Arabic, sans-serif' font-size='40' font-weight='bold' fill='%23B45309' text-anchor='middle'%3eد.ع%3c/text%3e%3c/svg%3e" alt="DinarLive Logo" className="h-10 w-10 sm:h-14 sm:w-14" />
                  <div>
                    <h1 className="text-2xl sm:text-4xl font-extrabold text-gray-900 dark:text-white tracking-tight">{t.appName}</h1>
                    <div className="relative h-6 sm:h-8 overflow-hidden mt-0.5">
                        <p key={activeConversionIdx} className="text-xs sm:text-lg text-sky-600 dark:text-sky-400 font-bold animate-slide-fade uppercase tracking-wide">
                            {conversions[activeConversionIdx]}
                        </p>
                    </div>
                  </div>
              </div>
              <div className="flex items-center gap-1 sm:gap-4 bg-white/60 dark:bg-gray-800/80 p-2 rounded-2xl shadow-xl border border-gray-200/50 dark:border-gray-700/50 backdrop-blur-xl">
                <ThemeToggle />
                <LanguageSelector currentLang={language} onChangeLang={setLanguage} />
                <div className="w-[1px] h-8 bg-gray-200 dark:bg-gray-700 mx-1"></div>
                <div className="relative group">
                    <button 
                    onClick={handleManualRefresh} 
                    className={`p-2.5 rounded-xl transition-all duration-300 shadow-sm flex items-center justify-center ${loading ? 'bg-sky-50 dark:bg-sky-900/40 text-sky-500' : cooldownSeconds > 0 ? 'bg-gray-100 dark:bg-gray-700 text-gray-400' : 'bg-sky-600 text-white hover:bg-sky-700 active:scale-95 shadow-sky-200 dark:shadow-sky-900/20 shadow-md'}`}
                    aria-label="Refresh rates"
                    >
                    <RefreshIcon className={`w-5 h-5 sm:w-6 sm:h-6 ${loading ? 'animate-spin' : ''}`} />
                    </button>
                    {cooldownMessage && (
                        <div className="absolute top-full right-0 mt-3 px-4 py-2 bg-gray-900 dark:bg-gray-100 text-white dark:text-black text-xs font-bold rounded-xl shadow-2xl whitespace-nowrap animate-fade-in z-50 border border-gray-700 dark:border-gray-300">
                            {cooldownMessage}
                        </div>
                    )}
                </div>
              </div>
            </div>

            <div className="flex items-center justify-center -mt-2">
                 {loading && !isCompletelyEmpty && (
                     <div className="flex items-center gap-2.5 px-6 py-2.5 bg-white/80 dark:bg-sky-900/20 rounded-full border border-sky-100 dark:border-sky-800 shadow-lg animate-pulse backdrop-blur-sm">
                        <span className="relative flex h-3 w-3">
                            <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-sky-400 opacity-75"></span>
                            <span className="relative inline-flex rounded-full h-3 w-3 bg-sky-500"></span>
                        </span>
                        <span className="text-xs sm:text-sm font-black text-sky-700 dark:text-sky-300 uppercase tracking-[0.2em]">{t.updatingRates}</span>
                     </div>
                 )}
            </div>
          </header>

          {error && (
            <div className="my-6 text-center text-red-500 bg-red-100 dark:bg-red-900/50 p-6 rounded-2xl transition-colors duration-300 animate-fade-in max-w-2xl mx-auto shadow-lg">
                <p className="text-lg font-semibold">{t.errorAfterRetriesTitle}</p>
                <p className="mt-2">{t.errorAfterRetriesMessage}</p>
                <button onClick={() => refetch()} className="mt-6 px-6 py-2.5 rounded-lg bg-sky-600 text-white font-semibold hover:bg-sky-700 active:bg-sky-800 transition-colors focus:outline-none focus:ring-2 focus:ring-sky-500 focus:ring-offset-2 dark:focus:ring-offset-gray-900">
                    {t.retryButton}
                </button>
            </div>
          )}

          {!error && (
            <div className="grid grid-cols-1 lg:grid-cols-5 gap-6 lg:gap-10">
              <div className="lg:col-span-2 space-y-6">
                <div className="space-y-6">
                    <Header t={t} />
                    {(loading && !rate) ? (
                        <div className="space-y-4">
                            <RateDisplaySkeleton />
                            <RateDisplaySkeleton />
                        </div>
                    ) : rate && (
                        <div className="space-y-8 animate-fade-in">
                            <RateDisplay
                                value={rateForDisplay}
                                loading={loading}
                                label={t.marketRateLabel}
                                description={t.marketRateDescription}
                                currency={t.iqdCurrency}
                                cities={rate.cities}
                                cityLabels={cityLabels}
                                trend={marketTrend}
                                highLow={marketHighLow}
                                isHero={true}
                            />
                            <RateDisplay
                                value={centralBankRateForDisplay}
                                loading={loading}
                                label={t.centralBankRateLabel}
                                description={t.centralBankRateDescription}
                                currency={t.iqdCurrency}
                            />
                        </div>
                    )}
                </div>

                <div>
                    {(loading && !rate) ? (
                        <ComparisonRatesSkeleton />
                    ) : rate && (
                        <ComparisonRates 
                            iqdRate={iqdRateValue}
                            eurRate={eurPerUsdValue}
                            tryRate={tryPerUsdValue}
                            gbpRate={gbpPerUsdValue}
                            irtRate={irtPerUsdValue}
                            t={t}
                            onCurrencySelect={handleCurrencySelect}
                        />
                    )}
                </div>

                {rate && (
                    <div className="bg-white dark:bg-gray-800/80 rounded-3xl shadow-2xl p-6 sm:p-8 animate-fade-in border border-gray-100 dark:border-gray-700/50">
                        <LastUpdated date={rate.updated} loading={loading} t={t} onRefresh={handleManualRefresh} cooldownSeconds={cooldownSeconds} />
                        <Footer onAboutClick={() => setIsAboutOpen(true)} onShareClick={handleShare} shareFeedback={shareFeedback} t={t} />
                    </div>
                )}
              </div>

              <div className="lg:col-span-3 space-y-8">
                <div className="space-y-4">
                    <button 
                        onClick={() => setIsChartOpen(prev => !prev)} 
                        className="w-full flex items-center justify-between p-4 px-6 rounded-2xl bg-gray-100/80 dark:bg-gray-800 hover:bg-gray-200 dark:hover:bg-gray-700/80 transition-all group border border-gray-200/50 dark:border-gray-700"
                    >
                        <h2 className="text-xl md:text-2xl font-black text-gray-800 dark:text-gray-100 tracking-tight">{t.rateHistoryTitle}</h2>
                        <div className="flex items-center gap-3">
                            <span className="text-xs font-bold text-gray-400 dark:text-gray-500 uppercase tracking-widest hidden sm:inline">{isChartOpen ? t.closeButton : 'Open'}</span>
                            <ChevronIcon className={`w-6 h-6 text-sky-500 transition-transform duration-500 ${isChartOpen ? 'rotate-180' : ''}`} />
                        </div>
                    </button>
                    <div className={`transition-all duration-700 ease-[cubic-bezier(0.4, 0, 0.2, 1)] overflow-hidden ${isChartOpen ? 'max-h-[600px] opacity-100 translate-y-0' : 'max-h-0 opacity-0 -translate-y-4'}`}>
                        {(loading && rateHistory.length === 0) ? <RateHistoryChartSkeleton /> : <RateHistoryChart history={rateHistory} t={t} />}
                    </div>
                </div>

                {rate && (
                    <div className="space-y-4 animate-fade-in">
                        <button 
                            onClick={() => setIsCalculatorOpen(prev => !prev)} 
                            className="w-full flex items-center justify-between p-4 px-6 rounded-2xl bg-gray-100/80 dark:bg-gray-800 hover:bg-gray-200 dark:hover:bg-gray-700/80 transition-all group border border-gray-200/50 dark:border-gray-700"
                        >
                            <h2 className="text-xl md:text-2xl font-black text-gray-800 dark:text-gray-100 tracking-tight">{t.calculatorTitle}</h2>
                            <div className="flex items-center gap-3">
                                <span className="text-xs font-bold text-gray-400 dark:text-gray-500 uppercase tracking-widest hidden sm:inline">{isCalculatorOpen ? t.closeButton : 'Open'}</span>
                                <ChevronIcon className={`w-6 h-6 text-sky-500 transition-transform duration-500 ${isCalculatorOpen ? 'rotate-180' : ''}`} />
                            </div>
                        </button>
                        <div className={`transition-all duration-700 ease-[cubic-bezier(0.4, 0, 0.2, 1)] overflow-hidden ${isCalculatorOpen ? 'max-h-[800px] opacity-100 translate-y-0' : 'max-h-0 opacity-0 -translate-y-4'}`}>
                            <Calculator rates={allRates} t={t} onCurrencySelect={handleCurrencySelect} />
                        </div>
                    </div>
                )}
              </div>
            </div>
          )}
        </main>
      </div>

      <Dialog isOpen={isAboutOpen} onClose={() => setIsAboutOpen(false)} title={t.aboutDialogTitle} t={t}>
        <p className="text-sm text-gray-600 dark:text-gray-300 whitespace-pre-line text-center leading-relaxed">{t.aboutDialogContent}</p>
      </Dialog>

      {modalState.currency && (
        <>
          <CurrencyInfoModal isOpen={modalState.view === 'info'} onClose={handleCloseModals} onBuy={handleBuyClick} currencyCode={modalState.currency} t={t} />
          <BuyCurrencyModal isOpen={modalState.view === 'buy'} onClose={handleCloseModals} currencyCode={modalState.currency} rates={allRates} t={t} />
        </>
      )}
      {!isCompletelyEmpty && (
        <>
            <ChatFab onClick={() => setIsChatOpen(true)} />
            <ChatDialog isOpen={isChatOpen} onClose={() => setIsChatOpen(false)} rate={rate} t={t} />
        </>
      )}

      <style>{`
        @keyframes slideFade {
          0% { transform: translateY(100%); opacity: 0; }
          15% { transform: translateY(0); opacity: 1; }
          85% { transform: translateY(0); opacity: 1; }
          100% { transform: translateY(-100%); opacity: 0; }
        }
        .animate-slide-fade { animation: slideFade 3s cubic-bezier(0.4, 0, 0.2, 1) infinite; }
        @keyframes fadeIn { from { opacity: 0; } to { opacity: 1; } }
        .animate-fade-in { animation: fadeIn 0.4s ease-out forwards; }
      `}</style>
    </>
  );
}

