import { BuyCurrencyModal } from './components/BuyCurrencyModal';

const ChevronIcon: React.FC<{ className?: string }> = ({ className }) => (
  <svg xmlns="http://www.w3.org/2000/svg" className={className} fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
    <path strokeLinecap="round" strokeLinejoin="round" d="M19 9l-7 7-7-7" />
  </svg>
);

const RefreshIcon: React.FC<{ className?: string }> = ({ className }) => (
    <svg xmlns="http://www.w3.org/2000/svg" className={className} fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2.5}>
        <path strokeLinecap="round" strokeLinejoin="round" d="M16.023 9.348h4.992v-.001M2.985 19.644v-4.992m0 0h4.992m-4.993 0l3.181 3.183a8.25 8.25 0 0013.803-3.7M4.031 9.865a8.25 8.25 0 0113.803-3.7l3.181 3.182m0-4.991v4.99" />
    </svg>
);

const isLargeScreen = () => {
    if (typeof window === 'undefined') return false;
    return window.matchMedia('(min-width: 1024px)').matches;
};

export default function App(): React.ReactElement {
  const { rate, loading, error, refetch, rateHistory, cooldownSeconds } = useExchangeRate();

  const [isCalculatorOpen, setIsCalculatorOpen] = useState(isLargeScreen());
  const [isChartOpen, setIsChartOpen] = useState(isLargeScreen());
  const [language, setLanguage] = useLanguage();
  const [isAboutOpen, setIsAboutOpen] = useState(false);
  const [isChatOpen, setIsChatOpen] = useState(false);
  const [shareFeedback, setShareFeedback] = useState('');
  const [isManualRefreshing, setIsManualRefreshing] = useState(false);
  const [cooldownMessage, setCooldownMessage] = useState<string | null>(null);
  const [modalState, setModalState] = useState<{ currency: string | null; view: 'info' | 'buy' }>({ currency: null, view: 'info' });
  const [activeConversionIdx, setActiveConversionIdx] = useState(0);
  const t = translations[language];

  const iqdRateValue = useMemo(() => rate?.iqd ?? 0, [rate]);
  const officialRateValue = useMemo(() => rate?.centralBankRate ?? 1310, [rate]);
  const eurPerUsdValue = useMemo(() => rate?.eurPerUsd ?? 0, [rate]);
  const tryPerUsdValue = useMemo(() => rate?.tryPerUsd ?? 0, [rate]);
  const gbpPerUsdValue = useMemo(() => rate?.gbpPerUsd ?? 0, [rate]);
  const irtPerUsdValue = useMemo(() => rate?.irtPerUsd ?? 0, [rate]);
  const rateForDisplay = iqdRateValue * 100;
  const centralBankRateForDisplay = officialRateValue * 100;

  const conversions = useMemo(() => [
      `${t.usd} ↔ ${t.iqd}`,
      `${t.eur} ↔ ${t.iqd}`,
      `${t.gbp} ↔ ${t.iqd}`,
      `${t.try} ↔ ${t.iqd}`,
      `${t.irt} ↔ ${t.iqd}`,
  ], [t]);

  useEffect(() => {
      const interval = setInterval(() => {
          setActiveConversionIdx(prev => (prev + 1) % conversions.length);
      }, 3000);
      return () => clearInterval(interval);
  }, [conversions]);

  const marketTrend = useMemo(() => {
    if (!rateHistory || rateHistory.length < 2) return undefined;
    const sortedHistory = [...rateHistory].sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime());
    const latestHistory = sortedHistory[sortedHistory.length - 1];
    const prevHistory = sortedHistory[sortedHistory.length - 2]; 
    let comparisonRate = latestHistory.rate;
    if (Math.abs(comparisonRate - rateForDisplay) < 1 && sortedHistory.length > 1) {
         comparisonRate = prevHistory.rate;
    }
    const diff = rateForDisplay - comparisonRate;
    const percentage = ((diff / comparisonRate) * 100).toFixed(2);
    return {
        direction: diff > 0 ? 'up' as const : diff < 0 ? 'down' as const : 'neutral' as const,
        percentage: Math.abs(parseFloat(percentage)).toString()
    };
  }, [rateHistory, rateForDisplay]);

  const marketHighLow = useMemo(() => {
      if (!rateHistory || rateHistory.length === 0) return undefined;
      const rates = rateHistory.map(r => r.rate);
      if (rateForDisplay > 0) rates.push(rateForDisplay);
      return { high: Math.max(...rates), low: Math.min(...rates) };
  }, [rateHistory, rateForDisplay]);

  const allRates = useMemo(() => ({
    IQD: iqdRateValue,
    USD: 1,
    EUR: eurPerUsdValue,
    TRY: tryPerUsdValue,
    GBP: gbpPerUsdValue,
    IRT: irtPerUsdValue,
  }), [iqdRateValue, eurPerUsdValue, tryPerUsdValue, gbpPerUsdValue, irtPerUsdValue]);

  const isCompletelyEmpty = loading && !rate && rateHistory.length === 0 && !error;
  const showFullScreenLoader = isCompletelyEmpty || isManualRefreshing;

  const handleManualRefresh = async () => {
    if (loading) return;
    if (cooldownSeconds > 0) {
        setCooldownMessage(t.refreshCooldown(`${cooldownSeconds}s`));
        setTimeout(() => setCooldownMessage(null), 2500);
        return;
    }
    setIsManualRefreshing(true);
    try {
        await refetch();
    } finally {
        setIsManualRefreshing(false);
    }
  };

  const handleShare = async () => {
    if (!rate) return;
    const shareText = t.shareMessage(Math.floor(rateForDisplay).toLocaleString(), centralBankRateForDisplay.toLocaleString());
    const shareData: ShareData = { title: t.headerTitle, text: shareText };
    const isShareableUrl = window.location.protocol.startsWith('http');
    if (isShareableUrl) shareData.url = window.location.href;

    if (navigator.share) {
      try { await navigator.share(shareData); } catch (err) { if ((err as Error).name !== 'AbortError') console.error('Error sharing:', err); }
    } else {
      try {
        const clipboardText = isShareableUrl ? `${shareText}\n\n${window.location.href}` : shareText;
        await navigator.clipboard.writeText(clipboardText);
        setShareFeedback(t.copiedToClipboard);
        setTimeout(() => setShareFeedback(''), 2000);
      } catch (err) { console.error('Error copying to clipboard:', err); }
    }
  };

  const handleCurrencySelect = (currencyCode: string) => {
    setModalState({ currency: currencyCode, view: 'info' });
  };
  const handleBuyClick = () => setModalState(prev => ({ ...prev, view: 'buy' }));
  const handleCloseModals = () => setModalState({ currency: null, view: 'info' });

  const cityLabels = useMemo(() => ({
    suly: t.sulyName,
    erbil: t.erbilName,
    duhok: t.duhokName,
    regional: t.regionalRatesTitle
  }), [t]);

  return (
    <>
      {showFullScreenLoader && <StartupLoader t={t} />}

      <div className={`min-h-screen w-full transition-filter duration-500 ${showFullScreenLoader ? 'blur-sm' : ''}`}>
        <main className="w-full max-w-7xl mx-auto p-4 sm:p-6 lg:p-8">

          <header className="mb-8 flex flex-col gap-6">
            <div className="flex justify-between items-start">
              <div className="flex items-center gap-3">
                  <img src="data:image/svg+xml,%3csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 100 100'%3e%3ccircle cx='50' cy='50' r='48' fill='%23FBBF24' stroke='%23B45309' stroke-width='4'/%3e%3ctext x='50' y='60' font-family='Noto Kufi Arabic, sans-serif' font-size='40' font-weight='bold' fill='%23B45309' text-anchor='middle'%3eد.ع%3c/text%3e%3c/svg%3e" alt="DinarLive Logo" className="h-10 w-10 sm:h-14 sm:w-14" />
                  <div>
                    <h1 className="text-2xl sm:text-4xl font-extrabold text-gray-900 dark:text-white tracking-tight leading-tight">{t.appName}</h1>
                    <div className="relative h-5 sm:h-7 overflow-hidden mt-0.5 flex items-center">
                        <p key={activeConversionIdx} className="w-full text-[10px] sm:text-base text-sky-600 dark:text-sky-400 font-bold animate-slide-fade uppercase tracking-wide leading-none whitespace-nowrap">
                            {conversions[activeConversionIdx]}
                        </p>
                    </div>
                  </div>
              </div>
              <div className="flex items-center gap-1 sm:gap-4 bg-white/60 dark:bg-gray-800/80 p-2 rounded-2xl shadow-xl border border-gray-200/50 dark:border-gray-700/50 backdrop-blur-xl">
                <ThemeToggle />
                <LanguageSelector currentLang={language} onChangeLang={setLanguage} />
                <div className="w-[1px] h-8 bg-gray-200 dark:bg-gray-700 mx-1"></div>
                <div className="relative group">
                    <button 
                    onClick={handleManualRefresh} 
                    className={`p-2.5 rounded-xl transition-all duration-300 shadow-sm flex items-center justify-center ${loading ? 'bg-sky-50 dark:bg-sky-900/40 text-sky-500' : cooldownSeconds > 0 ? 'bg-gray-100 dark:bg-gray-700 text-gray-400' : 'bg-sky-600 text-white hover:bg-sky-700 active:scale-95 shadow-sky-200 dark:shadow-sky-900/20 shadow-md'}`}
                    aria-label="Refresh rates"
                    >
                    <RefreshIcon className={`w-5 h-5 sm:w-6 sm:h-6 ${loading ? 'animate-spin' : ''}`} />
                    </button>
                    {cooldownMessage && (
                        <div className="absolute top-full right-0 mt-3 px-4 py-2 bg-gray-900 dark:bg-gray-100 text-white dark:text-black text-xs font-bold rounded-xl shadow-2xl whitespace-nowrap animate-fade-in z-50 border border-gray-700 dark:border-gray-300">
                            {cooldownMessage}
                        </div>
                    )}
                </div>
              </div>
            </div>

            <div className="flex items-center justify-center -mt-2">
                 {loading && !isCompletelyEmpty && (
                     <div className="flex items-center gap-2.5 px-6 py-2.5 bg-white/80 dark:bg-sky-900/20 rounded-full border border-sky-100 dark:border-sky-800 shadow-lg animate-pulse backdrop-blur-sm">
                        <span className="relative flex h-3 w-3">
                            <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-sky-400 opacity-75"></span>
                            <span className="relative inline-flex rounded-full h-3 w-3 bg-sky-500"></span>
                        </span>
                        <span className="text-xs sm:text-sm font-black text-sky-700 dark:text-sky-300 uppercase tracking-[0.2em]">{t.updatingRates}</span>
                     </div>
                 )}
            </div>
          </header>

          {error && (
            <div className="my-6 text-center text-red-500 bg-red-100 dark:bg-red-900/50 p-6 rounded-2xl transition-colors duration-300 animate-fade-in max-w-2xl mx-auto shadow-lg">
                <p className="text-lg font-semibold">{t.errorAfterRetriesTitle}</p>
                <p className="mt-2">{t.errorAfterRetriesMessage}</p>
                <button onClick={() => refetch()} className="mt-6 px-6 py-2.5 rounded-lg bg-sky-600 text-white font-semibold hover:bg-sky-700 active:bg-sky-800 transition-colors focus:outline-none focus:ring-2 focus:ring-sky-500 focus:ring-offset-2 dark:focus:ring-offset-gray-900">
                    {t.retryButton}
                </button>
            </div>
          )}

          {!error && (
            <div className="grid grid-cols-1 lg:grid-cols-5 gap-6 lg:gap-10">
              <div className="lg:col-span-2 space-y-6">
                <div className="space-y-6">
                    <Header t={t} />
                    {(loading && !rate) ? (
                        <div className="space-y-4">
                            <RateDisplaySkeleton />
                            <RateDisplaySkeleton />
                        </div>
                    ) : rate && (
                        <div className="space-y-8 animate-fade-in">
                            <RateDisplay
                                value={rateForDisplay}
                                loading={loading}
                                label={t.marketRateLabel}
                                description={t.marketRateDescription}
                                currency={t.iqdCurrency}
                                cities={rate.cities}
                                cityLabels={cityLabels}
                                trend={marketTrend}
                                highLow={marketHighLow}
                                isHero={true}
                            />
                            <RateDisplay
                                value={centralBankRateForDisplay}
                                loading={loading}
                                label={t.centralBankRateLabel}
                                description={t.centralBankRateDescription}
                                currency={t.iqdCurrency}
                            />
                        </div>
                    )}
                </div>

                <div>
                    {(loading && !rate) ? (
                        <ComparisonRatesSkeleton />
                    ) : rate && (
                        <ComparisonRates 
                            iqdRate={iqdRateValue}
                            eurRate={eurPerUsdValue}
                            tryRate={tryPerUsdValue}
                            gbpRate={gbpPerUsdValue}
                            irtRate={irtPerUsdValue}
                            t={t}
                            onCurrencySelect={handleCurrencySelect}
                        />
                    )}
                </div>

                {rate && (
                    <div className="bg-white dark:bg-gray-800/80 rounded-3xl shadow-2xl p-6 sm:p-8 animate-fade-in border border-gray-100 dark:border-gray-700/50">
                        <LastUpdated date={rate.updated} loading={loading} t={t} onRefresh={handleManualRefresh} cooldownSeconds={cooldownSeconds} />
                        <Footer onAboutClick={() => setIsAboutOpen(true)} onShareClick={handleShare} shareFeedback={shareFeedback} t={t} />
                    </div>
                )}
              </div>

              <div className="lg:col-span-3 space-y-8">
                <div className="space-y-4">
                    <button 
                        onClick={() => setIsChartOpen(prev => !prev)} 
                        className="w-full flex items-center justify-between p-4 px-6 rounded-2xl bg-gray-100/80 dark:bg-gray-800 hover:bg-gray-200 dark:hover:bg-gray-700/80 transition-all group border border-gray-200/50 dark:border-gray-700"
                    >
                        <h2 className="text-xl md:text-2xl font-black text-gray-800 dark:text-gray-100 tracking-tight">{t.rateHistoryTitle}</h2>
                        <div className="flex items-center gap-3">
